444	export async function runMigration(job: Job): Promise<void> {
445	  const migration = await loadMigration(job);
446	  const items = (migration.items ?? {}) as MigrationItems;
447	  const paths = items.paths ?? [];
448	  const target = migration.server;
449	  const targetName = target ? target.label || target.hostname : "your server";
450	
451	  // The post-cutover certificate pass shares this handler (and therefore the
452	  // already-registered MIGRATE JobType) but is NOT a migration: it copies
453	  // nothing and must never fall through into the transfer below.
454	  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
455	    try {
456	      // HARD CEILING. This worker is strictly serial: whatever is in this
457	      // function is the only thing the platform is doing. The pass opens SSH to a
458	      // customer's box and runs certbot, and on the sweep's first live run a
459	      // single unresponsive target left the job RUNNING through two reap cycles
460	      // — with a new customer's provisioning job queued behind it. A background
461	      // nicety must never be able to stall the queue that provisions servers.
462	      await Promise.race([
463	        runPostCutoverTls(migration, items),
464	        new Promise<never>((_, reject) =>
465	          setTimeout(() => reject(new Error("post-cutover TLS pass exceeded its time budget")), TLS_PASS_TIMEOUT_MS)
466	        ),
467	      ]);
468	    } catch (e) {
469	      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
470	      // Swallowed on purpose: a failed certificate retry must not mark the
471	      // customer's finished migration as failed, and must not make the job loop
472	      // retry a phase that will keep failing for the same reason. The sweep will
473	      // come back to it on its own schedule.
474	    }
475	    return;
476	  }
477	
478	  // Fresh start (also lets a retried job re-enter cleanly).
479	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
480	  await db.migration.update({
481	    where: { id: migration.id },
482	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
483	  });
484	
485	  // Shared progress reporter: threads the bounded log tail through each update so
486	  // both the real engine and the simulation write to the same Migration row.
487	  const reportStep = async (progress: number, step: string, line: string) => {
488	    log = await report(migration.id, progress, step, line, log);
489	  };
490	
491	  try {
492	    if (REAL_MIGRATION) {
493	      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
494	      // Resolve the TLS inputs BEFORE the engine starts. These three arguments
495	      // are what make the certificate ladder reachable at all — see
496	      // resolveTlsInputs for the failure each dropped argument caused.
497	      const tls = await resolveTlsInputs(migration.userId);
498	      if (tls.note) await reportStep(5, "Starting", `HTTPS: ${tls.note}.`);
499	
500	      const summary = await runRealMigration({
501	        migration: {
502	          id: migration.id,
503	          sourceHost: migration.sourceHost,
504	          sourcePort: migration.sourcePort,
505	          sourceUser: migration.sourceUser,
506	          sourcePasswordEnc: migration.sourcePasswordEnc,
507	        },
508	        target: target as any,
509	        items,
510	        report: reportStep,
511	        // Rung 3 of the certificate ladder: a wildcard (`*.domain`) can ONLY be
512	        // issued with a DNS-01 challenge, so a multi-tenant app is stuck on a
513	        // certificate warning without this token.
514	        cloudflareToken: tls.cloudflareToken,
515	        // Without this every cert is `--register-unsafely-without-email` and
516	        // Let's Encrypt has nobody to warn before it expires.
517	        acmeEmail: tls.acmeEmail,
518	        // Hostnames the customer registered with us, folded into the published
519	        // set and the certificate SANs when they belong to a served site.
520	        knownDomains: tls.knownDomains,
521	      });
522	
523	      // The engine returns an HONEST outcome. A run that executed every step but
524	      // left a source domain dark — or a migrated unit crash-looping — is NOT a
525	      // success, and must never be written back as one.
526	      //
527	      // This line is why the 2026-07-25 migration reported "Completed" while the
528	      // customer's site served a certificate warning and then Apache's default
529	      // page: the status was hardcoded, so no amount of verification downstream
530	      // could change what the customer was told. `COMPLETED_WITH_ISSUES` is
531	      // terminal (MigrationWizard treats it as an end state) but visibly distinct.
532	      const clean = summary.outcome === "COMPLETED";
533	      const unserved = summary.unservedDomains ?? [];
534	      await db.migration.update({
535	        where: { id: migration.id },
536	        data: {
537	          status: clean ? "DONE" : "COMPLETED_WITH_ISSUES",
538	          progress: 100,
539	          step: clean ? "Completed" : "Finished — some sites need attention",
540	          finishedAt: new Date(),
541	        },
542	      });
543	      // Persist the honest step-by-step summary (secret-free) into items.results.
544	      await clearSecrets(migration.id, items, summary.results);
545	
546	      const workDir = migrationWorkDir(migration.id);
547	      const running = summary.verifiedRunning.length;
548	      const manual = summary.needsAttention.length;
549	      const tail =
550	        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. ` +
551	        `Your old server is untouched — if anything looks wrong, point DNS back to it while we sort this out.`;
552	      // Lead with the bad news when there is bad news. Burying dark domains under
553	      // a "completed" headline is what cost the customer a working site.
554	      const body = clean
555	        ? `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
556	          `${manual} copied that may need a manual step. ` +
557	          (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
558	          tail
559	        : `Lift-and-shift onto ${targetName} finished, but it is NOT fully live yet. ` +
560	          (unserved.length
561	            ? `These site(s) are not serving on the new server: ${unserved.slice(0, 8).join(", ")}${unserved.length > 8 ? ` (+${unserved.length - 8} more)` : ""}. `
562	            : "") +
563	          `${(summary.outcomeReasons ?? []).join("; ")}. ` +
564	          `${running} item(s) verified running. ` +
565	          tail;
566	      await notify(
567	        migration.userId,
568	        clean
569	          ? `Migration to ${targetName} completed`
570	          : `Migration to ${targetName} finished — ${unserved.length || "some"} site(s) need attention`,
571	        body,
572	        "/dashboard/migrate"
573	      );
574	      return;
575	    }
576	
577	    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
578	    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
579	    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
580	    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
581	    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
582	    const composeDirs = items.composeDirs ?? [];
583	    const webServers = items.webServers ?? [];
584	    const runtimes = items.runtimes ?? [];
585	    const verifyPorts = items.verifyPorts ?? [];
586	    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
587	    const simResults: MigrationStepResult[] = [];
588	
589	    await reportStep(6, "Connecting…", `Connecting to your Nxeon server (${targetName}) to prepare the lift-and-shift.`);
590	    await sleep(SANDBOX ? 500 : 1000);
591	    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
592	    await sleep(SANDBOX ? 400 : 800);
593	
594	    // Prerequisites stage.
595	    const prereqLabels: string[] = [];
596	    if (dbEngines.includes("mysql")) prereqLabels.push("MySQL/MariaDB server");
597	    if (dbEngines.includes("postgres")) prereqLabels.push("PostgreSQL server");
598	    if (hasContainers) prereqLabels.push("Docker Engine + compose");
599	    for (const w of webServers) prereqLabels.push(w === "nginx" ? "nginx" : "Apache");
600	    for (const rt of runtimes) prereqLabels.push(rt === "nodejs" ? "Node.js" : "Python 3 + pip");
601	    if (prereqLabels.length) {
602	      await reportStep(18, "Installing prerequisites…", `Installing on ${targetName}: ${prereqLabels.join(", ")}.`);
603	      for (const lbl of prereqLabels) {
604	        await sleep(SANDBOX ? 200 : 400);
605	        await reportStep(20, "Installing prerequisites…", `  ${lbl}: installed.`);
606	        simResults.push({ step: `Install ${lbl}`, status: "running", detail: "installed" });
607	      }
608	    }
609	
610	    // Files stage — same-path copy.
611	    await reportStep(30, "Copying files…", paths.length ? `Copying ${paths.length} path(s) to the same locations on ${targetName}.` : "No file paths selected — skipping file copy.");
612	    for (const p of paths) {
613	      await sleep(SANDBOX ? 200 : 400);
614	      await reportStep(40, "Copying files…", `  rsync ${p} → ${p}`);
615	    }
616	    if (paths.length) simResults.push({ step: `Copy ${paths.length} folder(s) to their original paths`, status: "copied", detail: "files placed at the same paths" });
617	
618	    // Databases — dump via source root LOCAL auth (no password), import on target.
619	    for (const eng of dbEngines) {
620	      await sleep(SANDBOX ? 300 : 600);
621	      if (eng === "mysql") {
622	        await reportStep(62, "Migrating databases…", "  mysqldump --all-databases via source root socket (no password) → mysql < dump on target.");
623	        simResults.push({ step: "Migrate MySQL/MariaDB databases", status: "copied", detail: "dumped via source root socket and imported" });
624	      } else {
625	        await reportStep(64, "Migrating databases…", "  sudo -u postgres pg_dumpall via peer auth → psql -f on target.");
626	        simResults.push({ step: "Migrate PostgreSQL databases", status: "copied", detail: "dumped via source postgres peer auth and imported" });
627	      }
628	    }
629	
630	    // Docker compose bring-up.
631	    for (const dir of composeDirs) {
632	      await sleep(SANDBOX ? 250 : 500);
633	      await reportStep(76, "Starting containers…", `  cd ${dir} && docker compose up -d`);
634	      simResults.push({ step: `Compose up ${dir}`, status: "running", detail: "docker compose up -d succeeded" });
635	    }
636	
637	    // Verification.
638	    await reportStep(92, "Verifying…", "Checking databases, containers and listening ports on the new server.");
639	    await sleep(SANDBOX ? 400 : 800);
640	    if (dbEngines.includes("mysql")) simResults.push({ step: "MySQL/MariaDB engine", status: "running", detail: "engine is active on the target" });
641	    if (dbEngines.includes("postgres")) simResults.push({ step: "PostgreSQL engine", status: "running", detail: "engine is active on the target" });
642	    if (hasContainers) {
643	      await reportStep(94, "Verifying…", `  docker ps shows ${composeDirs.length || 1} running container(s).`);
644	      simResults.push({ step: "Docker containers", status: "running", detail: `${composeDirs.length || 1} container(s) running` });
645	    }
646	    if (verifyPorts.length) {
647	      await reportStep(95, "Verifying…", `  ports up: ${verifyPorts.join(", ")}.`);
648	      simResults.push({ step: "Listening ports", status: "running", detail: `now listening: ${verifyPorts.join(", ")}` });
649	    }
650	
651	    const simRunning = simResults.filter((r) => r.status === "running").length;
652	    const simManual = simResults.filter((r) => r.status === "copied" || r.status === "failed").length;
653	    await reportStep(98, "Finalising…", `Migrated & running (verified): ${simRunning}. Copied — may need a manual step: ${simManual}.`);
654	    await sleep(SANDBOX ? 300 : 600);
655	
656	    await db.migration.update({
657	      where: { id: migration.id },
658	      data: { status: "DONE", progress: 100, step: "Completed", finishedAt: new Date() },
659	    });
660	    // Security: drop all source credentials now that the job is done; persist summary.
661	    await clearSecrets(migration.id, items, simResults);
662	
663	    await notify(
664	      migration.userId,
665	      `Migration to ${targetName} completed`,
666	      `Lift-and-shift onto ${targetName} finished: ${simRunning} item(s) migrated & running, ${simManual} copied. Point your DNS at the new server when ready.`,
667	      "/dashboard/migrate"
668	    );
669	  } catch (e: any) {
670	    const lastError = `${e?.message ?? e}`.slice(0, 1000);
671	    console.error(`[migrate] migration ${migration.id} failed:`, e);
672	    log = appendLog(log, `ERROR: ${lastError}`);
673	    await db.migration
674	      .update({
675	        where: { id: migration.id },
676	        data: { status: "FAILED", step: "Failed", lastError, log, finishedAt: new Date() },
677	      })
678	      .catch(() => {});
679	    // Security: clear the stored source password/DB secrets even on failure.
680	    await clearSecrets(migration.id, items).catch(() => {});
681	    await notify(
682	      migration.userId,
683	      `Migration to ${targetName} failed`,
684	      lastError,
685	      "/dashboard/migrate"
686	    );
687	    // Swallow — the failure is recorded on the Migration row. Re-throwing would
688	    // make the job loop retry a migration whose secrets we've already cleared.
689	  }
690	}
