431	/**
432	 * True when a reference cannot come from a public registry — a LOCALLY-BUILT
433	 * tag. A registry host is the first `/`-segment when it contains a `.` (domain)
434	 * or `:` (host:port), or is exactly `localhost`. `ns/name` with neither is
435	 * either Docker Hub or a local build tag and cannot be told apart by name, so we
436	 * treat it as local: a `docker save`/`load` always works, whereas guessing
437	 * "pullable" wrongly leaves the customer's container permanently dead (exactly
438	 * what happened with `studionexis/frontend:latest` in the field).
439	 * MUST match isLocalImageRef in worker/migrate-detect.ts.
440	 */
441	function isLocalImageRef(ref: string): boolean {
442	  const bare = ref.split("@")[0];
443	  const slash = bare.indexOf("/");
444	  if (slash < 0) return false; // Docker Hub library image, e.g. `redis:7-alpine`
445	  const head = bare.slice(0, slash);
446	  if (head === "localhost") return true;
447	  return !(head.includes(".") || head.includes(":"));
448	}
