450	/** A hostname we are willing to serve / probe (lowercased, wildcard stripped). */
451	function normalizeDomain(raw: string): string | null {
452	  const h = clean(raw, 253).toLowerCase().replace(/^["']|["']$/g, "").replace(/^\*\./, "").replace(/\.$/, "");
453	  if (!h || h === "localhost" || h === "_" || h === "default_server") return null;
454	  if (!DOMAIN_RE.test(h)) return null;
455	  if (/^\d+(\.\d+)*$/.test(h)) return null; // an IP is not a vhost name
456	  const tld = h.slice(h.lastIndexOf(".") + 1);
457	  if (tld.length < 2 || /\d/.test(tld)) return null;
458	  return h;
459	}
