475	// ---- SSH plumbing ---------------------------------------------------------
476	function execRemote(
477	  conn: Client,
478	  cmd: string,
479	  timeoutMs: number
480	): Promise<{ code: number; stdout: string; stderr: string }> {
481	  return new Promise((resolve, reject) => {
482	    conn.exec(cmd, (err, stream: ClientChannel) => {
483	      if (err) return reject(err);
484	      let stdout = "";
485	      let stderr = "";
486	      const timer = setTimeout(() => {
487	        try {
488	          stream.close();
489	        } catch {
490	          /* ignore */
491	        }
492	        reject(new Error("remote command timed out"));
493	      }, timeoutMs);
494	      stream
495	        .on("close", (code: number) => {
496	          clearTimeout(timer);
497	          resolve({ code: code ?? 0, stdout, stderr });
498	        })
499	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
500	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
501	    });
502	  });
503	}
504	
505	type ExecResult = { code: number; stdout: string; stderr: string };
506	
507	/**
508	 * `execRemote` that never throws — a timed-out or broken command reports exit 1
509	 * with its reason in `stderr`. Every best-effort step uses this so one failed
510	 * probe can never abort the whole migration.
511	 */
512	function sh(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<ExecResult> {
513	  return execRemote(conn, cmd, timeoutMs).catch((e) => ({
514	    code: 1,
515	    stdout: "",
516	    stderr: String(e?.message ?? e),
517	  }));
518	}
519	
520	/** `sh` reduced to a boolean "did it succeed". */

520	/** `sh` reduced to a boolean "did it succeed". */
521	async function shOk(conn: Client, cmd: string, timeoutMs: number = SETUP_TIMEOUT_MS): Promise<boolean> {
522	  return (await sh(conn, cmd, timeoutMs)).code === 0;
523	}
