525	// ---- Heartbeats for the long steps ----------------------------------------
526	/**
527	 * A single remote command can legitimately run for MINUTES — `apt-get install`,
528	 * `docker save | ssh | docker load`, `certbot certonly`. During that time the
529	 * engine emits nothing, so the customer's progress bar freezes and the run looks
530	 * hung.
531	 *
532	 * Seen live on 2026-07-25: the run sat silent on 89% "Securing your site…" for a
533	 * full TEN MINUTES while a certbot install blocked on needrestart. The customer
534	 * had no way to tell a wedged migration from a slow one.
535	 *
536	 * So the long steps run inside this wrapper, which emits ONE cheap line every
537	 * `everyMs` naming what is still running and for how long. It is deliberately
538	 * dumb: no extra SSH traffic, no state on the target, and a failing `say` can
539	 * never affect the work it is narrating.
540	 */
541	const HEARTBEAT_MS = 45_000;
542	
543	async function withHeartbeat<T>(
544	  what: string,
545	  say: (line: string) => Promise<void>,
546	  run: () => Promise<T>,
547	  everyMs: number = HEARTBEAT_MS
548	): Promise<T> {
549	  const started = Date.now();
550	  let saying = false;
551	  const timer = setInterval(() => {
552	    // Never let two heartbeats overlap, and never let a reporting failure
553	    // surface as an unhandled rejection — this is narration, not work.
554	    if (saying) return;
555	    saying = true;
556	    const secs = Math.round((Date.now() - started) / 1000);
557	    const elapsed = secs >= 120 ? `${Math.round(secs / 60)} min` : `${secs}s`;
558	    Promise.resolve(say(`  Still working: ${what} (${elapsed} so far) — this step can take a while.`))
559	      .catch(() => {})
560	      .finally(() => {
561	        saying = false;
562	      });
563	  }, Math.max(15_000, everyMs));
564	  // `unref` keeps a stray interval from holding the worker process open.
565	  (timer as unknown as { unref?: () => void }).unref?.();
566	  try {
567	    return await run();
568	  } finally {
569	    clearInterval(timer);
570	  }
571	}
