573	/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
574	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
575	  return new Promise((resolve, reject) => {
576	    const ws = sftp.createWriteStream(path, { mode: 0o600 });
577	    ws.on("close", () => resolve());
578	    ws.on("error", (e: Error) => reject(e));
579	    ws.end(Buffer.from(content, "utf8"));
580	  });
581	}
582	
583	function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
584	  return new Promise((resolve, reject) => {
585	    const target = connectionTarget(server as any);
586	    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
587	    const password = serverRootPassword(server);
588	    if (!password) return reject(new Error("target server has no root password on record"));
589	    const conn = new Client();
590	    conn.on("ready", () => {
591	      conn.sftp((err, sftp) => {
592	        if (err) return reject(err);
593	        resolve({ conn, sftp });
594	      });
595	    });
596	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
597	    conn.connect({
598	      host: target.host,
599	      port: target.port,
600	      username: "root",
601	      password,
602	      readyTimeout: CONNECT_TIMEOUT_MS,
603	    });
604	  });
605	}
