607	// ---- Prerequisite install (FIXED allowlist — never source-supplied) -------
608	// `mysql`        → MariaDB server (the MariaDB path, and the transparent fallback).
609	// `mysql_oracle` → Oracle MySQL server (installed when the source runs Oracle MySQL,
610	//                  so the restore is a clean same-engine import). Every package
611	//                  string below is a compile-time constant; the CHOICE between keys
612	//                  comes from a validated detected enum, never a source-supplied string.
613	type PkgKey =
614	  | "docker" | "mysql" | "mysql_oracle" | "postgresql" | "nginx" | "apache" | "nodejs" | "python3"
615	  // Installed on demand by the TLS step, never from a derived plan.
616	  | "certbot" | "certbot_dns_cloudflare";
617	
618	// Command that succeeds iff the package's main binary is already present.
619	const PKG_CHECK: Record<PkgKey, string> = {
620	  docker: "command -v docker >/dev/null 2>&1",
621	  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
622	  mysql_oracle: "command -v mysqld >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1",
623	  postgresql: "command -v psql >/dev/null 2>&1",
624	  nginx: "command -v nginx >/dev/null 2>&1",
625	  apache: "command -v apache2 >/dev/null 2>&1 || command -v httpd >/dev/null 2>&1",
626	  nodejs: "command -v node >/dev/null 2>&1",
627	  python3: "command -v python3 >/dev/null 2>&1",
628	  certbot: "command -v certbot >/dev/null 2>&1",
629	  certbot_dns_cloudflare: "certbot plugins 2>/dev/null | grep -q dns-cloudflare",
630	};
631	// Debian/Ubuntu (apt) package strings — the primary target for Nxeon servers.
632	const PKG_APT: Record<PkgKey, string> = {
633	  docker: "docker.io docker-compose-plugin",
634	  mysql: "mariadb-server mariadb-client",
635	  mysql_oracle: "mysql-server mysql-client",
636	  postgresql: "postgresql",
637	  nginx: "nginx",
638	  apache: "apache2",
639	  nodejs: "nodejs npm",
640	  python3: "python3 python3-pip",
641	  certbot: "certbot",
642	  certbot_dns_cloudflare: "python3-certbot-dns-cloudflare",
643	};
644	// RHEL/Fedora (dnf/yum) fallback package strings.
645	const PKG_DNF: Record<PkgKey, string> = {
646	  docker: "docker docker-compose-plugin",
647	  mysql: "mariadb-server mariadb",
648	  mysql_oracle: "mysql-server mysql",
649	  postgresql: "postgresql-server postgresql",
650	  nginx: "nginx",
651	  apache: "httpd",
652	  nodejs: "nodejs npm",
653	  python3: "python3 python3-pip",
654	  certbot: "certbot",
655	  certbot_dns_cloudflare: "python3-certbot-dns-cloudflare",
656	};
657	// A friendly label for the log/summary.
658	const PKG_LABEL: Record<PkgKey, string> = {
659	  docker: "Docker Engine + compose",
660	  mysql: "MariaDB server",
661	  mysql_oracle: "MySQL server (Oracle)",
662	  postgresql: "PostgreSQL server",
663	  nginx: "nginx",
664	  apache: "Apache",
665	  nodejs: "Node.js",
666	  python3: "Python 3 + pip",
667	  certbot: "Certbot (Let's Encrypt)",
668	  certbot_dns_cloudflare: "Certbot Cloudflare DNS plugin",
669	};
