752	// ---- Plan derivation (prefer explicit items, re-validate everything) ------
753	function derivePlan(items: Items) {
754	  const scan = items.scan ?? {};
755	
756	  // Engines to dump: explicit dbEngines, else engines the scan marked present.
757	  const engineSet = new Set<string>();
758	  for (const e of items.dbEngines ?? []) engineSet.add(e);
759	  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
760	  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");
761	
762	  // Which MySQL-family engine to install on the target, from the DETECTED variant:
763	  // Oracle MySQL → mysql-server (clean same-engine); MariaDB (or undeterminable) →
764	  // mariadb-server (the existing safe default). This is a validated enum, never a
765	  // source string; it only selects a fixed package-allowlist KEY.
766	  const mysqlDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "mysql");
767	  const mysqlVariant: "mysql" | "mariadb" = mysqlDetail?.variant === "mysql" ? "mysql" : "mariadb";
768	  const mysqlVersion: string | null = mysqlDetail?.version ?? null;
769	  const pgDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "postgres");
770	  const pgVersion: string | null = pgDetail?.version ?? null;
771	
772	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
773	  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
774	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
775	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
776	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
777	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
778	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
779	  const containers = (scan.containers ?? [])
780	    .map((c) => ({
781	      name: String(c?.name ?? ""),
782	      image: String(c?.image ?? ""),
783	      ports: String(c?.ports ?? ""),
784	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
785	    }))
786	    .slice(0, 30);
787	
788	  const prereqs: PkgKey[] = [];
789	  // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
790	  if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
791	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
792	  if (hasContainers) prereqs.push("docker");
793	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
794	  for (const rt of runtimes) prereqs.push(rt);
795	
796	  return { dbEngines, mysqlVariant, mysqlVersion, pgVersion, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes, services, containers, prereqs };
797	}
