889	/** Parse docker's human size label ("1.23GB", "345MB", "12.3kB") into bytes. */
890	function parseDockerSize(label: string): number {
891	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(clean(label, 32));
892	  if (!m) return 0;
893	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
894	  return Math.max(0, Math.round(parseFloat(m[1]) * (mult[m[2].toUpperCase()] ?? 1)));
