897	function human(n: number): string {
898	  if (!Number.isFinite(n) || n <= 0) return "0 B";
899	  const u = ["B", "KB", "MB", "GB", "TB"];
900	  let i = 0;
901	  let v = n;
902	  while (v >= 1024 && i < u.length - 1) {
903	    v /= 1024;
904	    i++;
905	  }
906	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
907	}
