1297	/**
1298	 * A device path we are willing to hand to mkfs/mount/blkid: a whole disk such as
1299	 * `/dev/sdb` and nothing else — no partitions, no `..`, no shell metacharacters,
1300	 * no device-mapper aliases.
1301	 */
1302	const DEVPATH_RE = /^\/dev\/[a-z][a-z0-9]{1,31}$/;
1303	
1304	/** Read `df` free bytes for a path (GNU `--output`, with a portable fallback). */
1305	async function availBytes(conn: Client, path: string): Promise<number | null> {
1306	  const r = await sh(conn, `df -B1 --output=avail ${path} 2>/dev/null | tail -n1`);
1307	  let n = Number(clean(r.stdout, 32));
1308	  if (!Number.isFinite(n) || n <= 0) {
1309	    const r2 = await sh(conn, `df -B1 ${path} 2>/dev/null | awk 'NR==2{print $4}'`);
1310	    n = Number(clean(r2.stdout, 32));
1311	  }
1312	  return Number.isFinite(n) && n > 0 ? n : null;
1313	}
