1315	/** Parse `lsblk -b -P` KEY="value" output into rows. */
1316	function parseLsblk(out: string): BlockDev[] {
1317	  const rows: BlockDev[] = [];
1318	  for (const line of (out ?? "").split("\n")) {
1319	    if (!line.trim()) continue;
1320	    const kv: Record<string, string> = {};
1321	    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) kv[m[1]] = m[2];
1322	    if (!kv.NAME) continue;
1323	    rows.push({
1324	      name: clean(kv.NAME, 64),
1325	      type: clean(kv.TYPE ?? "", 32),
1326	      sizeBytes: Number(kv.SIZE) || 0,
1327	      fstype: clean(kv.FSTYPE ?? "", 32),
1328	      mount: clean(kv.MOUNTPOINT ?? kv.MOUNTPOINTS ?? "", 255),
1329	      pkname: clean(kv.PKNAME ?? "", 64),
1330	    });
1331	  }
1332	  return rows;
1333	}
