1335	/**
1336	 * Find EVERY block device on the TARGET that is attached but completely unused.
1337	 * A disk qualifies ONLY if all of these hold — the bar is deliberately absolute,
1338	 * because the cost of getting it wrong is destroying a customer's data:
1339	 *
1340	 *   • TYPE=disk (a whole device, never a partition/LVM/crypt node),
1341	 *   • no FSTYPE on the device itself,
1342	 *   • no partitions or children of ANY kind carved out of it,
1343	 *   • no mountpoint anywhere in its tree (walked via PKNAME, so an LVM or
1344	 *     dm-crypt stack rooted on the disk still disqualifies it),
1345	 *   • it is not the disk carrying the root filesystem,
1346	 *   • `blkid` finds NO signature at all on it,
1347	 *   • nothing in /sys/block/<dev>/holders is using it,
1348	 *   • it is at least MIN_EXTRA_DISK_BYTES.
1349	 *
1350	 * A real migration had a 20 GB volume sitting idle in exactly this state while
1351	 * the root disk filled to 92% and the builds died.
1352	 *
1353	 * Returned largest-first, and ALL of them, so the caller can tell the customer
1354	 * honestly what is attached ("2 unused volumes, largest is 30 GB") even though
1355	 * only ONE is ever used — separate volumes are separate filesystems and the
1356	 * engine deliberately does not weld them together. Every name has passed
1357	 * BLOCKDEV_RE, so it is safe to interpolate into a command.
1358	 *
1359	 * Finding a disk here does NOT mean it will be touched: that needs explicit
1360	 * customer consent (`useVolumeForDocker`).
1361	 */
1362	async function findUnusedDisks(conn: Client): Promise<BlockDev[]> {
1363	  const ls = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
1364	  if (ls.code !== 0) return [];
1365	  const rows = parseLsblk(ls.stdout);
1366	  if (!rows.length) return [];
1367	
1368	  const byName = new Map(rows.map((r) => [r.name, r]));
1369	  /** Walk PKNAME up to the top-level device (bounded — never trust a cycle). */
1370	  const topOf = (name: string): string => {
1371	    let cur = name;
1372	    for (let i = 0; i < 8; i++) {
1373	      const row = byName.get(cur);
1374	      if (!row?.pkname || row.pkname === cur) break;
1375	      cur = row.pkname;
1376	    }
1377	    return cur;
1378	  };
1379	
1380	  // Any disk with a filesystem or a mountpoint ANYWHERE in its tree is out.
1381	  const inUse = new Set<string>();
1382	  for (const r of rows) if (r.fstype || r.mount) inUse.add(topOf(r.name));
1383	
1384	  // Belt and braces: never touch the disk that backs `/`, however it is stacked.
1385	  const rs = await sh(conn, `findmnt -n -o SOURCE / 2>/dev/null | head -n1`);
1386	  const rootSrc = clean(rs.stdout, 128);
1387	  if (/^\/dev\/[A-Za-z0-9/_-]{1,64}$/.test(rootSrc)) {
1388	    inUse.add(topOf(rootSrc.slice(rootSrc.lastIndexOf("/") + 1)));
1389	    const pk = await sh(conn, `lsblk -no PKNAME ${rootSrc} 2>/dev/null | head -n1`);
1390	    const d = clean(pk.stdout, 64);
1391	    if (d) inUse.add(topOf(d));
1392	  }
1393	
1394	  const candidates = rows.filter(
1395	    (d) =>
1396	      d.type === "disk" &&
1397	      !d.fstype &&
1398	      !d.mount &&
1399	      BLOCKDEV_RE.test(d.name) &&
1400	      !inUse.has(d.name) &&
1401	      d.sizeBytes >= MIN_EXTRA_DISK_BYTES &&
1402	      // no partitions / LVM / crypt children carved out of it
1403	      !rows.some((o) => o.name !== d.name && (o.pkname === d.name || topOf(o.name) === d.name))
1404	  );
1405	  if (!candidates.length) return [];
1406	
1407	  // Final per-device confirmation, immediately before the caller writes anything.
1408	  const blank: BlockDev[] = [];
1409	  for (const c of candidates) if (await verifyBlank(conn, c.name)) blank.push(c);
1410	  blank.sort((a, b) => b.sizeBytes - a.sizeBytes);
1411	  return blank;
1412	}
