1414	/**
1415	 * Re-confirm, in ONE round trip, that a device is untouched: no blkid signature
1416	 * of any kind, not mounted, no device-mapper/md holder, no children. Every check
1417	 * must come back negative — anything ambiguous means "hands off".
1418	 */
1419	async function verifyBlank(conn: Client, name: string): Promise<boolean> {
1420	  if (!BLOCKDEV_RE.test(name)) return false;
1421	  const r = await sh(
1422	    conn,
1423	    `blkid /dev/${name} >/dev/null 2>&1 && echo SIG; ` +
1424	      `findmnt -S /dev/${name} >/dev/null 2>&1 && echo MOUNTED; ` +
1425	      `[ -n "$(ls -A /sys/block/${name}/holders 2>/dev/null)" ] && echo HELD; ` +
1426	      `[ -n "$(lsblk -no NAME /dev/${name} 2>/dev/null | tail -n +2)" ] && echo CHILD; ` +
1427	      `echo READY`
1428	  );
1429	  const out = clean(r.stdout, 256);
1430	  return out.includes("READY") && !/SIG|MOUNTED|HELD|CHILD/.test(out);
1431	}
