1433	/**
1434	 * Persist an ALREADY-FORMATTED filesystem at EXTRA_DISK_MOUNT: fstab entry by
1435	 * UUID (never by device name — an added volume can come back as a different
1436	 * /dev/sdX) with `nofail` so a missing disk cannot wedge the boot, then mount.
1437	 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
1438	 * a no-op. NEVER formats — the caller owns that decision.
1439	 */
1440	async function mountExtraFs(conn: Client, devPath: string): Promise<{ ok: boolean; detail: string }> {
1441	  if (!DEVPATH_RE.test(devPath)) return { ok: false, detail: "device path failed validation" };
1442	  const bl = await sh(conn, `blkid -s UUID -o value ${devPath} 2>/dev/null`);
1443	  const uuid = clean(bl.stdout, 64);
1444	  if (!UUID_RE.test(uuid)) return { ok: false, detail: "could not read a valid filesystem UUID" };
1445	
1446	  await sh(conn, `mkdir -p ${EXTRA_DISK_MOUNT}`);
1447	  await sh(
1448	    conn,
1449	    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s ext4 defaults,nofail 0 2\\n' '${uuid}' '${EXTRA_DISK_MOUNT}' >> /etc/fstab`
1450	  );
1451	  const mnt = await sh(
1452	    conn,
1453	    `mountpoint -q ${EXTRA_DISK_MOUNT} || mount ${EXTRA_DISK_MOUNT} 2>&1 || mount ${devPath} ${EXTRA_DISK_MOUNT} 2>&1`,
1454	    SETUP_TIMEOUT_MS
1455	  );
1456	  const mounted = await shOk(conn, `mountpoint -q ${EXTRA_DISK_MOUNT}`);
1457	  if (!mounted) return { ok: false, detail: `mount failed: ${tailOf(mnt)}` };
1458	  return { ok: true, detail: `mounted at ${EXTRA_DISK_MOUNT} (fstab UUID entry, nofail)` };
1459	}
