1461	/** Format + persistently mount ONE blank disk at EXTRA_DISK_MOUNT. Idempotent. */
1462	async function prepareExtraDisk(conn: Client, dev: string): Promise<{ ok: boolean; detail: string }> {
1463	  if (!BLOCKDEV_RE.test(dev)) return { ok: false, detail: "device name failed validation" };
1464	  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data /dev/${dev} 2>&1`, INSTALL_TIMEOUT_MS);
1465	  if (mk.code !== 0) return { ok: false, detail: `mkfs.ext4 failed: ${tailOf(mk)}` };
1466	  const m = await mountExtraFs(conn, `/dev/${dev}`);
1467	  if (!m.ok) return m;
1468	  return { ok: true, detail: `formatted ext4 and ${m.detail}` };
1469	}
