1471	/**
1472	 * Move Docker's on-disk state onto the extra volume BEFORE anything is pulled,
1473	 * loaded or built.
1474	 *
1475	 * BOTH stores are relocated. `/var/lib/containerd` is a SEPARATE store from
1476	 * `/var/lib/docker`: with the containerd image store that `get.docker.com`
1477	 * installs on Ubuntu 22.04, image layers and build ingest
1478	 * (`io.containerd.content.v1.content/ingest/…`) live under containerd. In the
1479	 * field, relocating only `/var/lib/docker` still let the root disk reach 100%
1480	 * with 9.4 GB parked in `/var/lib/containerd`. Bind mounts are used for both, so
1481	 * one mechanism covers both stores regardless of which image store is active and
1482	 * without rewriting a daemon.json we do not own.
1483	 *
1484	 * Safety: the daemons are stopped first, data is rsynced (not moved) and the old
1485	 * directory is only deleted after the bind mount is CONFIRMED live.
1486	 */
1487	async function relocateDockerStores(
1488	  conn: Client,
1489	  say: (line: string) => Promise<void>
1490	): Promise<{ moved: string[]; failed: string[] }> {
1491	  const moved: string[] = [];
1492	  const failed: string[] = [];
1493	  await sh(conn, `systemctl stop docker.socket docker containerd 2>/dev/null; true`, SETUP_TIMEOUT_MS);
1494	
1495	  for (const store of DOCKER_STORES) {
1496	    const leaf = store.slice(store.lastIndexOf("/") + 1);
1497	    const dest = `${EXTRA_DISK_MOUNT}/${leaf}`;
1498	    // Already relocated (a re-run, or the previous attempt got this far)?
1499	    const already = await sh(conn, `findmnt -n -o SOURCE --target ${store} 2>/dev/null`);
1500	    if (clean(already.stdout, 255).startsWith(EXTRA_DISK_MOUNT)) {
1501	      moved.push(`${store} (already on ${EXTRA_DISK_MOUNT})`);
1502	      continue;
1503	    }
1504	    await sh(conn, `mkdir -p ${dest} ${store}`);
1505	    const cp = await sh(conn, `rsync -a --numeric-ids ${store}/ ${dest}/ 2>&1`, TRANSFER_TIMEOUT_MS);
1506	    if (cp.code !== 0) {
1507	      failed.push(`${store}: copy failed (${tailOf(cp)})`);
1508	      continue;
1509	    }
1510	    await sh(
1511	      conn,
1512	      `grep -q " ${store} none bind" /etc/fstab || printf '%s %s none bind,nofail 0 0\\n' '${dest}' '${store}' >> /etc/fstab`
1513	    );
1514	    // Empty the original only AFTER the copy succeeded, and keep it aside until
1515	    // the bind mount is confirmed.
1516	    await sh(conn, `rm -rf ${store}.premigrate && mv ${store} ${store}.premigrate && mkdir -p ${store}`, SETUP_TIMEOUT_MS);
1517	    const mnt = await sh(conn, `mount --bind ${dest} ${store} 2>&1`, SETUP_TIMEOUT_MS);
1518	    const live = await shOk(conn, `mountpoint -q ${store}`);
1519	    if (!live) {
1520	      // Roll back cleanly — better a full root disk than a broken Docker.
1521	      await sh(conn, `rmdir ${store} 2>/dev/null; mv ${store}.premigrate ${store} 2>/dev/null; true`);
1522	      await sh(conn, `sed -i '\\| ${store} none bind|d' /etc/fstab 2>/dev/null; true`);
1523	      failed.push(`${store}: bind mount failed (${tailOf(mnt)}) — left in place`);
1524	      continue;
1525	    }
1526	    await sh(conn, `rm -rf ${store}.premigrate 2>/dev/null; true`, SETUP_TIMEOUT_MS);
1527	    moved.push(store);
1528	  }
1529	
1530	  await sh(conn, `systemctl enable --now containerd 2>/dev/null; systemctl enable --now docker 2>/dev/null; true`, INSTALL_TIMEOUT_MS);
1531	  const df = await sh(conn, `df -h ${DOCKER_STORES.join(" ")} 2>/dev/null | tail -n +2`);
1532	  // cleanLines: `clean` strips the newlines this split depends on, collapsing the
1533	  // whole df table into one unreadable row.
1534	  const dfTail = cleanLines(df.stdout, 400).split("\n").map((l) => l.trim()).filter(Boolean).join(" | ");
1535	  if (dfTail) await say(`  Docker storage now: ${dfTail}`);
1536	  return { moved, failed };
1537	}
