1539	/**
1540	 * Reclaim build/ingest space. `docker builder prune -af` reclaimed 7.1 GB in the
1541	 * field immediately after two image builds, which is the difference between a
1542	 * working bring-up and ENOSPC. Dangling images go too. Deliberately NOT
1543	 * `image prune -a` / `container prune` — those would delete images we have just
1544	 * transferred but not yet started.
1545	 */
1546	async function pruneDocker(conn: Client): Promise<number> {
1547	  const before = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
1548	  await sh(conn, `docker builder prune -af >/dev/null 2>&1; docker image prune -f >/dev/null 2>&1; true`, INSTALL_TIMEOUT_MS);
1549	  const after = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
1550	  return Math.max(0, after - before);
1551	}
