1553	// ===========================================================================
1554	// DOCKER IMAGES — pull public, save/load everything else
1555	// ===========================================================================
1556	/**
1557	 * Make one image exist on the TARGET.
1558	 *
1559	 *   already present → nothing (a re-run must not re-transfer gigabytes)
1560	 *   public registry → `docker pull` (fast, and costs no source bandwidth)
1561	 *   otherwise       → `docker save | gzip` on the source, streamed straight
1562	 *                     through the SSH channel into `gunzip | docker load`
1563	 *
1564	 * The locally-built case is the one that silently broke a real migration: the
1565	 * engine copied files and named volumes but never the IMAGE, so standalone
1566	 * containers could never start. A pull that fails also falls back to save/load,
1567	 * so a private registry the new box cannot authenticate to still works.
1568	 *
1569	 * `ref` is validated by validImageRef before it reaches any command; success is
1570	 * confirmed with `docker image inspect` rather than trusting an exit code
1571	 * through a pipeline.
1572	 */
1573	async function ensureImage(
1574	  conn: Client,
1575	  ref: string,
1576	  local: boolean,
1577	  onSource: (cmd: string) => string,
1578	  priv: string,
1579	  say: (line: string) => Promise<void>
1580	): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
1581	  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };
1582	
1583	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1584	    return { status: "present", detail: "already on the new server" };
1585	  }
1586	
1587	  if (!local) {
1588	    // A multi-gigabyte pull is one of the three steps that can sit silent for
1589	    // minutes, so it narrates itself (see withHeartbeat).
1590	    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
1591	      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
1592	    );
1593	    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1594	      return { status: "pulled", detail: "pulled from its registry" };
1595	    }
1596	    const why = tailOf(pull, 1, 120);
1597	    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
1598	  }
1599	
1600	  // `docker save | gzip -1` on the source → `gunzip | docker load` on the target,
1601	  // through the SSH channel we already hold. gzip -1 because these links are
1602	  // usually faster than the CPU and the layers are mostly already compressed.
1603	  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
1604	  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
1605	    sh(conn, stream, IMAGE_TIMEOUT_MS)
1606	  );
1607	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1608	    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
1609	  }
1610	  const why = tailOf(r, 2, 180);
1611	  return {
1612	    status: "failed",
1613	    detail: isEnospc(why)
1614	      ? "ran out of disk while loading the image"
1615	      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
1616	  };
1617	}
