1622	type ContainerPlan = {
1623	  name: string;
1624	  image: string;
1625	  restart: string;
1626	  ports: SrcPort[];
1627	  binds: { src: string; dest: string; ro: boolean }[];
1628	  volumes: { name: string; dest: string; ro: boolean }[];
1629	  network: string; // "" = default bridge
1630	  hostNetwork: boolean;
1631	  runuser: string;
1632	  workdir: string;
1633	  privileged: boolean;
1634	  caps: string[];
1635	  /** Non-empty ⇒ we refuse to recreate and log what a human has to do instead. */
1636	  blockers: string[];
1637	};

