1639	/**
1640	 * Turn one inspected source container into a plan we are willing to execute, or
1641	 * into a list of BLOCKERS explaining why we will not.
1642	 *
1643	 * The rule is absolute: a value either passes its allowlist and goes into the
1644	 * command, or the whole container is refused and logged. Nothing is sanitized,
1645	 * nothing arbitrary is ever executed. That is why an overridden Cmd/Entrypoint
1646	 * is a blocker — re-tokenising a shell string safely is not possible, so we say
1647	 * so instead of guessing.
1648	 */
1649	function planContainer(c: SrcContainer): ContainerPlan {
1650	  const blockers: string[] = [];
1651	  const plan: ContainerPlan = {
1652	    name: c.name, image: c.image, restart: "unless-stopped", ports: [], binds: [], volumes: [],
1653	    network: "", hostNetwork: false, runuser: "", workdir: "", privileged: false, caps: [], blockers,
1654	  };
1655	
1656	  if (!CONTNAME_RE.test(c.name)) blockers.push("container name is not reproducible safely");
1657	  if (!validImageRef(c.image)) blockers.push("image reference is not reproducible safely");
1658	
1659	  // Restart policy: keep the source's, but upgrade "no"/unset to unless-stopped
1660	  // so a reboot of the new server does not take the site down.
1661	  plan.restart = RESTART_POLICIES.has(c.restart) && c.restart !== "no" ? c.restart : "unless-stopped";
1662	
1663	  // Cmd / Entrypoint overrides cannot be re-tokenised safely.
1664	  if (c.cmd !== c.imagecmd) blockers.push("it runs a custom command (docker run … <cmd>)");
1665	  if (c.entrypoint !== c.imageentrypoint) blockers.push("it runs a custom entrypoint");
1666	  if (c.devices > 0) blockers.push(`it maps ${c.devices} host device(s)`);
1667	
1668	  for (const p of c.ports) {
