1727	/** Assemble the `docker run` command. Every interpolated value is pre-validated. */
1728	function buildRunCommand(p: ContainerPlan, envFile: string): string {
1729	  const a: string[] = ["docker", "run", "-d", "--name", p.name, "--restart", p.restart];
1730	  if (p.hostNetwork) a.push("--network", "host");
1731	  else if (p.network) a.push("--network", p.network);
1732	  if (p.runuser) a.push("--user", p.runuser);
1733	  if (p.workdir) a.push("-w", p.workdir);
1734	  if (p.privileged) a.push("--privileged");
1735	  for (const c of p.caps) a.push("--cap-add", c);
1736	  if (!p.hostNetwork) {
1737	    for (const port of p.ports) {
1738	      const hp = port.hostIp ? `${port.hostIp}:${port.hostPort}` : String(port.hostPort);
1739	      a.push("-p", `${hp}:${port.containerPort}/${port.proto}`);
1740	    }
1741	  }
1742	  for (const b of p.binds) a.push("-v", `${b.src}:${b.dest}${b.ro ? ":ro" : ""}`);
1743	  for (const v of p.volumes) a.push("-v", `${v.name}:${v.dest}${v.ro ? ":ro" : ""}`);
1744	  a.push("--env-file", envFile, p.image);
