1776	/**
1777	 * Parse `nginx -T` (the source's FULLY MERGED, running configuration) into vhost
1778	 * intent.
1779	 *
1780	 * WHY intent and not the files: blind-copying the source's `/etc/nginx` over the
1781	 * target's is what broke a real cutover in seven separate ways. The source was
1782	 * HestiaCP on nginx 1.25; the target is stock Ubuntu nginx 1.18. The copy
1783	 * replaced the target's `nginx.conf` (so its `include sites-enabled/*` vanished
1784	 * and any vhost written there was silently ignored), carried `listen
1785	 * <old-ip>:80` into 21 files (`bind() to <old ip>:80 failed` — nginx would not
1786	 * start at all), referenced certificates and `options-ssl-nginx.conf` that do
1787	 * not exist here, used `http2 on;` which 1.18 rejects as an unknown directive,
1788	 * pointed at log directories that do not exist, and installed a catch-all
1789	 * default server proxying to a dead port that answered 502 for every request.
1790	 *
1791	 * So: read the source's intent, then GENERATE a clean configuration in the
1792	 * target's own dialect, leaving the target's nginx.conf and include layout
1793	 * untouched. The source tree is kept as a read-only reference copy for the
1794	 * customer instead of being installed.
1795	 */
1796	export function parseNginxDump(lines: string[]): SrcVhost[] {
1797	  const upstreams = new Map<string, number>();
1798	  const out: SrcVhost[] = [];
1799	  let depth = 0;
1800	  let cur: SrcVhost | null = null;
1801	  let curDepth = 0;
1802	  let upName = "";
1803	  let upDepth = -1;
1804	
1805	  for (const raw of lines) {
1806	    const line = clean(raw, 1000).trim();
1807	    if (!line || line.startsWith("#")) continue;
1808	    const opens = (line.match(/\{/g) ?? []).length;
1809	    const closes = (line.match(/\}/g) ?? []).length;
1810	    const d = line.replace(/;\s*$/, "").trim();
1811	
1812	    // upstream blocks, so `proxy_pass http://myapp` resolves to a real port.
1813	    // Both the multi-line and the `upstream x { server 1.2.3.4:80; }` one-liner
1814	    // shapes occur in real configs, so the inline body is scanned too.
1815	    const um = /^upstream\s+([A-Za-z0-9._-]{1,64})\s*\{/.exec(line);
1816	    if (!cur && um) {
1817	      upName = um[1];
1818	      upDepth = depth;
1819	      const inline = /(?:^|;|\{)\s*server\s+[A-Za-z0-9._-]+:(\d{1,5})/.exec(line.slice(um[0].length));
1820	      if (inline) {
1821	        const p = Number(inline[1]);
1822	        if (Number.isInteger(p) && p >= 1 && p <= 65535) upstreams.set(upName, p);
1823	      }
1824	      depth += opens - closes;
1825	      if (depth <= upDepth) {
1826	        upName = "";
1827	        upDepth = -1;
1828	      }
1829	      continue;
1830	    }
1831	    if (upName) {
1832	      const sm = /^server\s+([A-Za-z0-9._-]+):(\d{1,5})/.exec(d);
1833	      if (sm && !upstreams.has(upName)) {
1834	        const p = Number(sm[2]);
1835	        if (Number.isInteger(p) && p >= 1 && p <= 65535) upstreams.set(upName, p);
1836	      }
1837	      depth += opens - closes;
1838	      if (depth <= upDepth) {
1839	        upName = "";
1840	        upDepth = -1;
1841	      }
1842	      continue;
1843	    }
1844	
1845	    if (!cur && /^server\s*\{/.test(line)) {
1846	      cur = { names: [], wildcard: "", proxyPort: 0, root: "", ssl: false, isDefault: false, ports: [] };
1847	      curDepth = depth;
1848	      depth += opens - closes;
1849	      continue;
1850	    }
1851	
1852	    if (cur) {
1853	      // Directives are matched ANYWHERE in the line, not just at its start, and
1854	      // independently rather than as an if/else chain: `nginx -T` reproduces the
1855	      // author's formatting, and one-liners like
1856	      // `location / { proxy_pass http://127.0.0.1:3720; }` are extremely common.
1857	      // Anchoring at the start silently loses the upstream and the site then
1858	      // looks unpublishable.
1859	      let m: RegExpExecArray | null;
1860	      if ((m = /(?:^|;|\{)\s*server_name\s+([^;{}]+)/.exec(d))) {
1861	        for (const t of m[1].split(/\s+/).slice(0, 12)) {
1862	          if (t === "_" || t === "localhost") {
1863	            cur.isDefault = true;
1864	            continue;
1865	          }
1866	          if (t.startsWith("*.")) {
1867	            const b = normalizeDomain(t.slice(2));
1868	            if (b) {
1869	              cur.wildcard = b;
1870	              if (!cur.names.includes(b)) cur.names.push(b);
1871	            }
1872	            continue;
1873	          }
1874	          const dm = normalizeDomain(t);
1875	          if (dm && !cur.names.includes(dm)) cur.names.push(dm);
1876	        }
1877	      }
1878	      if ((m = /(?:^|;|\{)\s*listen\s+([^;{}]+)/.exec(d))) {
1879	        const toks = m[1].trim().split(/\s+/);
1880	        const addr = toks[0];
1881	        let port = 0;
1882	        if (/^\d{1,5}$/.test(addr)) port = Number(addr);
1883	        else {
1884	          const pm = /^(?:\[[0-9a-fA-F:]+\]|[0-9.]+):(\d{1,5})$/.exec(addr);
1885	          if (pm) port = Number(pm[1]);
1886	        }
1887	        if (Number.isInteger(port) && port >= 1 && port <= 65535 && !cur.ports.includes(port)) cur.ports.push(port);
1888	        if (toks.includes("ssl") || port === 443) cur.ssl = true;
1889	        if (toks.includes("default_server") || toks.includes("default")) cur.isDefault = true;
1890	      }
1891	      if ((m = /(?:^|;|\{)\s*root\s+([^;{}\s]+)/.exec(d))) {
1892	        const p = m[1].replace(/\/$/, "");
1893	        if (validPath(p) && !cur.root) cur.root = p;
1894	      }
1895	      if ((m = /(?:^|;|\{)\s*proxy_pass\s+([^;{}\s]+)/.exec(d))) {
1896	        const pm = /^https?:\/\/([A-Za-z0-9._-]+)(?::(\d{1,5}))?/.exec(m[1]);
1897	        if (pm && !cur.proxyPort) {
1898	          if (pm[2]) {
1899	            const p = Number(pm[2]);
1900	            if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
1901	          } else {
1902	            const up = upstreams.get(pm[1]);
1903	            if (up) cur.proxyPort = up;
1904	          }
1905	        }
1906	      }
1907	      depth += opens - closes;
1908	      if (depth <= curDepth) {
1909	        if (cur.names.length) out.push(cur);
1910	        cur = null;
1911	      }
1912	      continue;
1913	    }
1914	
1915	    depth += opens - closes;
1916	    if (depth < 0) depth = 0;
1917	  }
1918	  return out;
1919	}
