1931	      if (pm) {
1932	        const p = Number(pm[1]);
1933	        if (Number.isInteger(p) && p >= 1 && p <= 65535) {
1934	          cur.ports.push(p);
1935	          if (p === 443) cur.ssl = true;
1936	        }
1937	      }
1938	      continue;
1939	    }
1940	    if (!cur) continue;
1941	    if (/^<\/VirtualHost/i.test(line)) {
1942	      if (cur.names.length) out.push(cur);
1943	      cur = null;
1944	      continue;
1945	    }
1946	    let m: RegExpExecArray | null;
1947	    if ((m = /^Server(?:Name|Alias)\s+(.+)$/i.exec(line))) {
1948	      for (const t of m[1].split(/\s+/).slice(0, 12)) {
1949	        if (t.startsWith("*.")) {
1950	          const b = normalizeDomain(t.slice(2));
1951	          if (b) {
1952	            cur.wildcard = b;
1953	            if (!cur.names.includes(b)) cur.names.push(b);
1954	          }
1955	          continue;
1956	        }
1957	        const dm = normalizeDomain(t);
1958	        if (dm && !cur.names.includes(dm)) cur.names.push(dm);
1959	      }
1960	    } else if ((m = /^DocumentRoot\s+"?([^"\s]+)"?$/i.exec(line))) {
1961	      const p = m[1].replace(/\/$/, "");
1962	      if (validPath(p)) cur.root = p;
1963	    } else if ((m = /^ProxyPass\s+\S+\s+(\S+)/i.exec(line))) {
1964	      const pm = /^https?:\/\/[A-Za-z0-9._-]+:(\d{1,5})/.exec(m[1]);
1965	      if (pm && !cur.proxyPort) {
1966	        const p = Number(pm[1]);
1967	        if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
1968	      }
