1976	/** One site as it will be SERVED on the target, after validation + reconciliation. */
1977	export type TargetSite = {
1978	  names: string[]; // validated, primary first; may include the wildcard base
1979	  wildcard: string; // "" or the base domain to add `*.base` for
1980	  proxyPort: number; // 0 ⇒ serve `root` instead
1981	  root: string;
1982	  certDomain: string; // "" unless a real certificate exists ON THE TARGET
