1986	/**
1987	 * Generate the migrated site configuration in the TARGET's own nginx dialect.
1988	 *
1989	 *  - `bindIp` is non-empty when the target's live config already has IP-bound
1990	 *    `listen` directives. nginx picks the most specific listen socket BEFORE it
1991	 *    ever looks at server_name, so a generic `listen 80` block loses to an
1992	 *    IP-bound one and the generated vhost would never be selected. Matching the
1993	 *    specificity is what makes it win (this bit twice in the field — once on 80,
1994	 *    once on 443, where it served the wrong certificate).
1995	 *  - `http2Directive` is true only on nginx ≥ 1.25, where `http2 on;` exists.
1996	 *    On 1.18 that directive is a hard config error, so HTTP/2 is folded into the
1997	 *    `listen` line instead.
1998	 *  - A TLS server block is emitted ONLY when the certificate files were verified
1999	 *    to exist on this machine. A config that references a missing certificate
2000	 *    stops nginx from starting at all — the worst possible outcome.
2001	 *
2002	 * Every interpolated value is pre-validated: domains by DOMAIN_RE, paths by
2003	 * PATH_RE, ports as integers. The file is written over SFTP, so no shell is
2004	 * involved in producing it.
2005	 */
2006	function buildMigratedNginxConf(sites: TargetSite[], bindIp: string, http2Directive: boolean): string {
2007	  const L: string[] = [
2008	    "# Generated by the Nxeon migration engine — do not hand-edit if you plan to",
2009	    "# re-run the migration; it rewrites this file. It is written for THIS",
2010	    "# server's nginx, not copied from the old one, so it cannot import the old",
2011	    "# server's paths, IP bindings, certificate locations or directive syntax.",
2012	    "",
2013	  ];
2014	  const listen = (port: number, extra: string) =>
2015	    bindIp ? `    listen ${bindIp}:${port}${extra};` : `    listen ${port}${extra};\n    listen [::]:${port}${extra};`;
2016	
2017	  const body = (s: TargetSite, indent: string): string[] => {
2018	    const b: string[] = [];
2019	    if (s.proxyPort) {
2020	      b.push(`${indent}client_max_body_size 64m;`);
2021	      b.push("");
2022	      b.push(`${indent}location / {`);
2023	      b.push(`${indent}    proxy_pass http://127.0.0.1:${s.proxyPort};`);
2024	      b.push(`${indent}    proxy_http_version 1.1;`);
2025	      b.push(`${indent}    proxy_set_header Host $host;`);
2026	      b.push(`${indent}    proxy_set_header X-Real-IP $remote_addr;`);
2027	      b.push(`${indent}    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;`);
2028	      b.push(`${indent}    proxy_set_header X-Forwarded-Proto $scheme;`);
2029	      b.push(`${indent}    proxy_set_header Upgrade $http_upgrade;`);
2030	      b.push(`${indent}    proxy_set_header Connection "upgrade";`);
2031	      b.push(`${indent}    proxy_read_timeout 300s;`);
2032	      b.push(`${indent}}`);
2033	    } else {
2034	      b.push(`${indent}root ${s.root};`);
2035	      b.push(`${indent}index index.php index.html index.htm;`);
2036	      b.push(`${indent}client_max_body_size 64m;`);
2037	      b.push("");
2038	      b.push(`${indent}location / {`);
2039	      b.push(s.phpSocket ? `${indent}    try_files $uri $uri/ /index.php?$query_string;` : `${indent}    try_files $uri $uri/ =404;`);
2040	      b.push(`${indent}}`);
2041	      if (s.phpSocket) {
2042	        b.push("");
2043	        b.push(`${indent}location ~ \\.php$ {`);
2044	        b.push(`${indent}    try_files $uri =404;`);
2045	        b.push(`${indent}    fastcgi_split_path_info ^(.+\\.php)(/.+)$;`);
2046	        b.push(`${indent}    fastcgi_pass unix:${s.phpSocket};`);
2047	        b.push(`${indent}    fastcgi_index index.php;`);
2048	        b.push(`${indent}    include fastcgi_params;`);
2049	        b.push(`${indent}    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`);
2050	        b.push(`${indent}}`);
2051	      }
2052	      b.push("");
2053	      b.push(`${indent}location ~ /\\. { deny all; }`);
2054	    }
2055	    return b;
2056	  };
2057	
2058	  for (const s of sites) {
2059	    const names = [...s.names];
2060	    if (s.wildcard) names.push(`*.${s.wildcard}`);
2061	    const nameList = names.join(" ");
2062	    L.push(`# ---- ${s.names[0]} ----`);
2063	    L.push("server {");
2064	    L.push(listen(80, ""));
2065	    L.push(`    server_name ${nameList};`);
2066	    L.push("");
2067	    L.push("    # Keep HTTP-01 certificate issue/renewal working.");
2068	    L.push("    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }");
2069	    L.push("");
2070	    if (s.certDomain) {
2071	      L.push("    location / { return 301 https://$host$request_uri; }");
2072	    } else {
2073	      L.push(...body(s, "    "));
2074	    }
2075	    L.push("}");
2076	    L.push("");
2077	    if (s.certDomain) {
2078	      L.push("server {");
2079	      L.push(listen(443, http2Directive ? " ssl" : " ssl http2"));
2080	      if (http2Directive) L.push("    http2 on;");
2081	      L.push(`    server_name ${nameList};`);
2082	      L.push("");
2083	      L.push(`    ssl_certificate /etc/letsencrypt/live/${s.certDomain}/fullchain.pem;`);
2084	      L.push(`    ssl_certificate_key /etc/letsencrypt/live/${s.certDomain}/privkey.pem;`);
2085	      L.push("    ssl_protocols TLSv1.2 TLSv1.3;");
2086	      L.push("    ssl_prefer_server_ciphers off;");
2087	      L.push("    ssl_session_cache shared:MIGSSL:10m;");
2088	      L.push("    ssl_session_timeout 1d;");
2089	      L.push("");
2090	      L.push(...body(s, "    "));
2091	      L.push("}");
2092	      L.push("");
2093	    }
2094	  }
2095	  return L.join("\n") + "\n";
2096	}
