2211	/**
2212	 * HTTP-probe one URL from the target itself and return its status code
2213	 * ("000" = nothing answered at all).
2214	 *
2215	 * `resolve` pins the hostname to 127.0.0.1 with `curl --resolve`, which sends the
2216	 * real Host header AND the real TLS SNI while never leaving the box. That is what
2217	 * makes this a genuine test of "will the customer's domain serve once DNS points
2218	 * here" — a plain port check proves only that something is listening, which is
2219	 * exactly how a migration can report success while the site returns 502 or the
2220	 * stock welcome page. `-k` because at probe time the name still resolves
2221	 * elsewhere; we are testing that the vhost matches and answers, not the chain.
2222	 */
2223	async function httpProbe(
2224	  conn: Client,
2225	  url: string,
2226	  resolve?: { domain: string; port: number }
2227	): Promise<{ code: string; body: string }> {
2228	  const res = resolve ? `--resolve ${resolve.domain}:${resolve.port}:127.0.0.1 ` : "";
2229	  // The BODY is fetched as well as the status, because a status code alone
2230	  // cannot tell a real site from the stock Apache/nginx default page — see
2231	  // defaultPageReason. It lands in a `mktemp` file rather than a fixed /tmp
2232	  // name: on a migrated multi-user box a predictable path under /tmp is a
2233	  // symlink-overwrite waiting to happen, and this engine never takes a
2234	  // destructive risk with the customer's files.
2235	  const r = await sh(
2236	    conn,
2237	    `f=$(mktemp 2>/dev/null || echo /dev/null); ` +
2238	      `c=$(curl -sS -k --max-time 12 ${res}-o "$f" -w '%{http_code}' ${url} 2>/dev/null); ` +
2239	      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 4096 "$f" 2>/dev/null; ` +
2240	      `[ "$f" = /dev/null ] || rm -f "$f"`,
2241	    SETUP_TIMEOUT_MS
2242	  );
2243	  const out = String(r.stdout ?? "");
2244	  const m = /NXCODE:(\d{3})/.exec(out);
2245	  const nl = out.indexOf("\n");
2246	  return { code: m ? m[1] : "000", body: probeBody(nl < 0 ? "" : out.slice(nl + 1)) };
2247	}
