2620	/**
2621	 * A unit file is the one thing in a migration that is copied VERBATIM and then
2622	 * executed. Everything inside it — interpreter path, working directory, build
2623	 * artefacts — is a statement about the OLD machine, and none of it is checked
2624	 * before `systemctl enable --now` runs.
2625	 *
2626	 * Real incident, 2026-07-25 (and this had happened BEFORE — it is field note #13,
2627	 * documented after a previous migration and it recurred anyway, which is exactly
2628	 * why it is now an executable pre-flight instead of a paragraph in a document):
2629	 *
2630	 *     nexis-next.service
2631	 *       ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
2632	 *
2633	 * The source had a hand-installed Node at /usr/local/bin/node. The target has
2634	 * apt's Node 20 at /usr/bin/node and NOTHING at /usr/local/bin/node, so systemd
2635	 * failed the exec with status 203/EXEC. The unit crash-looped 78 times and the
2636	 * migration reported SUCCESS.
2637	 *
2638	 * So: before enabling anything, resolve the absolute executable of every
2639	 * ExecStart / ExecStartPre / ExecStartPost. Missing ⇒ symlink to the same binary
2640	 * found elsewhere on the target, else copy it from the source, else BLOCK and say
2641	 * exactly which unit wants exactly which path.
2642	 */
2643	export type UnitExecRef = { directive: string; path: string };
2644	
2645	/**
2646	 * Fold systemd's line continuations. A unit may legally spread one ExecStart over
2647	 * several lines with a trailing backslash, and reading it line-at-a-time would
2648	 * see a directive whose command is empty and skip the check entirely.
2649	 */
2650	export function unfoldUnitLines(text: string): string[] {
2651	  const out: string[] = [];
2652	  let acc = "";
2653	  for (const raw of String(text ?? "").split("\n")) {
2654	    const line = raw.replace(/\r$/, "");
2655	    if (/\\\s*$/.test(line)) {
2656	      acc += line.replace(/\\\s*$/, " ");
2657	      continue;
2658	    }
2659	    out.push((acc + line).trim());
2660	    acc = "";
2661	  }
2662	  if (acc.trim()) out.push(acc.trim());
2663	  return out;
2664	}
2665	
2666	/**
2667	 * Every ABSOLUTE executable path a unit's Exec* directives will try to run.
2668	 *
2669	 * Defensive by design, because a unit file is untrusted input from another
2670	 * machine:
2671	 *   - `ExecStart=-/path`  the `-` (ignore failure), `@` (argv[0] override),
2672	 *     `+` (full privileges), `!` / `!!` (no-setuid variants) prefixes may appear
2673	 *     in any order and combination and are stripped before the path is read;
2674	 *   - quoted paths (`ExecStart="/opt/my app/bin/run" --flag`) are unquoted;
2675	 *   - an EMPTY assignment (`ExecStart=`) is systemd's list-reset and is skipped;
2676	 *   - a bare command (`ExecStart=node server.js`) is resolved from PATH by
2677	 *     systemd itself, so it is deliberately IGNORED — we cannot check it and
2678	 *     guessing would be worse than silence;
2679	 *   - a path carrying a `%` specifier (`/usr/bin/%i`) can only be resolved by
2680	 *     systemd, so it is skipped rather than mis-reported. It also would not pass
2681	 *     PATH_RE, which is what keeps every value here shell-inert.
2682	 */
2683	export function parseUnitExecPaths(text: string): UnitExecRef[] {
2684	  const out: UnitExecRef[] = [];
2685	  const seen = new Set<string>();
2686	  for (const line of unfoldUnitLines(text)) {
2687	    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
2688	    if (!m) continue;
2689	    let rhs = m[2].trim();
2690	    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
2691	    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
2692	    if (!rhs) continue;
2693	    let exe: string;
2694	    const q = rhs[0];
2695	    if (q === '"' || q === "'") {
2696	      const end = rhs.indexOf(q, 1);
2697	      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
2698	    } else {
2699	      exe = rhs.split(/\s+/)[0] ?? "";
2700	    }
2701	    exe = exe.trim();
2702	    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
2703	    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
2704	    const key = `${m[1]}|${exe}`;
2705	    if (seen.has(key) || out.length >= 12) continue;
2706	    seen.add(key);
2707	    out.push({ directive: m[1], path: exe });
2708	  }
2709	  return out;
2710	}
