2712	/**
2713	 * Everything `preflightUnitExecs` needs from the target machine, as an
2714	 * interface rather than a `Client`.
2715	 *
2716	 * WHY: field note #13 ("resolve ExecStart binaries") was written after a unit
2717	 * crash-looped 880 times, was never implemented, and the SAME failure came back
2718	 * four months later as #25 (`/usr/local/bin/node`, 78 restarts, migration
2719	 * reported success). The fix is only a fix if it stays correct, and it can only
2720	 * be kept correct by a test — so the one decision ladder that stands between a
2721	 * copied unit and a permanent crash-loop is driven through this seam and
2722	 * exercised by `test/migration-gate.test.ts` with a fake host. Nothing here is
2723	 * mocked in production: `sshUnitExecHost` is the only implementation the engine
2724	 * uses.
2725	 */
2726	export type UnitExecHost = {
2727	  /** The unit file's text; "" when it cannot be read. */
2728	  readUnitFile: (unitFile: string) => Promise<string>;
2729	  /** `test -x` — present AND executable. */
2730	  isExecutable: (path: string) => Promise<boolean>;
2731	  /** `test -e` — present at all (a non-executable file is still a 203/EXEC cause). */
2732	  exists: (path: string) => Promise<boolean>;
2733	  /** `command -v <basename>` — the same program installed under a different prefix. */
2734	  whichSameName: (basename: string) => Promise<string>;
2735	  /**
2736	   * `<path> --version` on the TARGET, and the same path's version on the SOURCE.
2737	   * Returns "" when the version cannot be read.
2738	   *
2739	   * WHY: step 1 of the repair ladder links a missing `/usr/local/bin/node` to
2740	   * whatever `node` the target happens to have and told the customer it was "the
2741	   * same program, installed in a different place". A source running Node 20 and a
2742	   * target with Node 12 are NOT the same program — the unit stops failing 203/EXEC
2743	   * and starts failing at runtime instead, which is harder to diagnose and reads
2744	   * as a successful repair. A version we did not compare is a claim we cannot make.
2745	   */
2746	  versionOf: (path: string) => Promise<string>;
2747	  versionOnSource: (path: string) => Promise<string>;
2748	  /** `mkdir -p <dir> && ln -s <target> <linkPath>`; true only if the link now execs. */
2749	  symlink: (opts: { target: string; linkPath: string; dir: string }) => Promise<boolean>;
2750	};
2751	
2752	/** The real, SSH-backed UnitExecHost — the only one production ever uses. */
2753	function sshUnitExecHost(conn: Client, onSource: (cmd: string) => string): UnitExecHost {
2754	  return {
2755	    readUnitFile: async (unitFile) => (await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS)).stdout,
2756	    isExecutable: (path) => shOk(conn, `test -x ${path}`),
2757	    exists: (path) => shOk(conn, `test -e ${path}`),

2758	    whichSameName: async (base) => clean((await sh(conn, `command -v ${base} 2>/dev/null`)).stdout, 255),
2759	    versionOf: async (path) =>
2760	      validPath(path) ? clean((await sh(conn, `${path} --version 2>/dev/null | head -n 1`, SETUP_TIMEOUT_MS)).stdout, 120) : "",
2761	    versionOnSource: async (path) =>
2762	      validPath(path)
2763	        ? clean((await sh(conn, `${onSource(`${path} --version 2>/dev/null | head -n 1`)}`, SETUP_TIMEOUT_MS)).stdout, 120)
2764	        : "",
2765	    symlink: async ({ target, linkPath, dir }) => {
2766	      // `ln -s` (not -sfn): we already proved the path is absent, so a plain
2767	      // symlink can never clobber anything. If a race created it meanwhile we
2768	      // want the loud failure, not a silent replacement.
2769	      const ok = await shOk(conn, `mkdir -p ${dir} && ln -s ${target} ${linkPath}`);
2770	      return ok && (await shOk(conn, `test -x ${linkPath}`));
2771	    },
2772	  };
2773	}
