2836	/**
2837	 * Resolve every missing Exec* binary for one unit BEFORE it is enabled.
2838	 * Returns the human-readable repairs made and a blocking entry for anything we
2839	 * refused to guess at. Never throws; never removes or overwrites anything —
2840	 * every action here only ever CREATES a path that did not exist.
2841	 */
2842	export async function preflightUnitExecs(opts: {
2843	  host: UnitExecHost;
2844	  unit: string;
2845	  unitFile: string;
2846	  existsOnSource: (path: string) => Promise<boolean>;
2847	  copyFromSource: (path: string) => Promise<boolean>;
2848	  say: (line: string) => Promise<void>;
2849	}): Promise<{ ok: boolean; repairs: string[]; blockers: PendingItem[] }> {
2850	  const { host, unit, unitFile, existsOnSource, copyFromSource, say } = opts;
2851	  const repairs: string[] = [];
2852	  const blockers: PendingItem[] = [];
2853	  if (!SVCNAME_RE.test(unit) || !validPath(unitFile)) return { ok: true, repairs, blockers };
2854	
2855	  const refs = parseUnitExecPaths(await host.readUnitFile(unitFile));
2856	  for (const ref of refs) {
2857	    if (await host.isExecutable(ref.path)) continue;
2858	
2859	    // It exists but is not executable — a real 203/EXEC cause too. Reported, not
2860	    // silently chmod-ed: changing the mode of the customer's own file is their
2861	    // call, and the command to do it is one line.
2862	    if (await host.exists(ref.path)) {
2863	      blockers.push({
2864	        domain: `${unit}.service`,
2865	        why: `its ${ref.directive} runs ${ref.path}, which exists on this server but is not executable — systemd will fail it with 203/EXEC`,
2866	        fix: `chmod +x ${ref.path} && systemctl restart ${unit}`,
2867	      });
2868	      continue;
2869	    }
2870	
2871	    // 1. The SAME program under a different prefix. This is the common case:
2872	    //    /usr/local/bin/node (hand-installed on the source) vs /usr/bin/node
2873	    //    (apt, on the target). A symlink makes the copied unit correct without
2874	    //    editing the customer's unit file.
2875	    const base = ref.path.slice(ref.path.lastIndexOf("/") + 1);
2876	    const dir = parentDir(ref.path);
2877	    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(base) && validPath(dir)) {
2878	      const found = await host.whichSameName(base);
2879	      if (found && found !== ref.path && validPath(found) && (await host.isExecutable(found))) {
2880	        if (await host.symlink({ target: found, linkPath: ref.path, dir })) {
2881	          // "The same program" is a claim, and until now it was made without ever
2882	          // checking. Compare the MAJOR versions across the two machines: linking
2883	          // a Node 20 app at a Node 12 interpreter stops the 203/EXEC and starts a
2884	          // runtime failure instead, which looks like a successful repair and is
2885	          // harder for the customer to diagnose. We still make the link (a wrong
2886	          // version at least produces a real error message rather than nothing),
2887	          // but a mismatch is reported as a blocker, not as a repair.
2888	          const [srcVer, dstVer] = await Promise.all([host.versionOnSource(ref.path), host.versionOf(found)]);
2889	          const srcMajor = majorVersion(srcVer);
2890	          const dstMajor = majorVersion(dstVer);
2891	          if (srcMajor && dstMajor && srcMajor !== dstMajor) {
2892	            blockers.push({
2893	              domain: `${unit}.service`,
2894	              why:
2895	                `its ${ref.directive} runs ${ref.path}. That program is not on this server, so it was linked to ${found} — but the old server had ` +
2896	                `${base} ${srcVer} and this one has ${base} ${dstVer}. That is a different major version, and an application built against ` +
2897	                `${base} ${srcMajor} will usually not run on ${base} ${dstMajor}`,
2898	              fix:
2899	                `install ${base} ${srcMajor} on this server (for Node: curl -fsSL https://deb.nodesource.com/setup_${srcMajor}.x | bash - && apt-get install -y nodejs), ` +
2900	                `then run: systemctl restart ${unit}`,
2901	            });
2902	            await say(
2903	              `  ${unit}: ${ref.path} was linked to ${found}, but the versions DIFFER — old server ${srcVer}, this server ${dstVer}. Check this service.`
2904	            );
2905	            continue;
2906	          }
2907	          const sameNote = srcMajor && dstMajor ? ` (both ${base} ${srcMajor})` : "";
2908	          repairs.push(`${unit}: ${ref.directive} wanted ${ref.path}, which is not on this server — linked it to ${found}${sameNote}`);
2909	          await say(`  ${unit}: ${ref.path} does not exist here, so it was linked to ${found} (the same program, installed in a different place)${sameNote}.`);
2910	          continue;
2911	        }
2912	      }
2913	    }
2914	
2915	    // 2. Not present under any name — bring the actual file across.
2916	    if (await existsOnSource(ref.path)) {
2917	      if (await copyFromSource(ref.path)) {
2918	        repairs.push(`${unit}: copied ${ref.path} from the old server so ${ref.directive} can run`);
2919	        await say(`  ${unit}: copied ${ref.path} across from the old server.`);
2920	        continue;
2921	      }
2922	    }
2923	
2924	    // 3. Refuse to guess. A unit that cannot exec is worth one loud line.
2925	    blockers.push({
2926	      domain: `${unit}.service`,
2927	      why:
2928	        `its ${ref.directive} runs ${ref.path}, which does not exist on this server and is not installed anywhere else here ` +
2929	        `(systemd fails this as 203/EXEC and restarts the service forever)`,
2930	      fix:
2931	        `install the program that provides ${base} on this server, then either symlink it — ln -s "$(command -v ${base})" ${ref.path} — ` +
2932	        `or edit ${unitFile} to the real path, and run: systemctl daemon-reload && systemctl restart ${unit}`,
2933	    });
2934	  }
2935	  return { ok: blockers.length === 0, repairs, blockers };
