3098	/**
3099	 * Parse `mysql -N -B -e "SELECT user, host FROM mysql.user"` into a set of
3100	 * `user@host` keys. `-B` is TAB-separated, one account per LINE.
3101	 *
3102	 * Incident (2026-07-26 rehearsal): this was `clean(stdout).split("\n").map(l =>
3103	 * l.split(/\s+/).slice(0,2).join("@"))`, and `clean` deletes BOTH separators, so
3104	 * the whole table collapsed into one garbage key like
3105	 * `readonly%shopapplocalhost`. Nothing ever matched, so `landed` was always
3106	 * empty and the run pushed — at status `failed`, the loudest the summary has —
3107	 * "none of the 3 application database account(s) could be recreated". Ground
3108	 * truth on that run: all three existed, with their original password hashes and
3109	 * grants, and the apps could log in. Field note 15's fix worked; only its
3110	 * verification lied. Since `failed` steps now drive the outcome, this single
3111	 * glued string also downgraded every migration that carried a DB account.
3112	 *
3113	 * A host column is optional in output shapes that omit it; a lone user name is
3114	 * still recorded so the caller can match on `user@%` if it must.
3115	 */
3116	export function parseMysqlUserList(stdout: string): Set<string> {
3117	  const out = new Set<string>();
3118	  for (const row of cleanRows(stdout, 8000)) {
3119	    // Tab is the -B separator; fall back to any whitespace run for `-t`/aligned
3120	    // output. User names may contain spaces in MySQL, but never a tab.
3121	    const cols = (row.includes("\t") ? row.split("\t") : row.split(/\s+/)).map((c) => c.trim()).filter(Boolean);
3122	    if (!cols.length) continue;
3123	    const [user, host] = cols;
3124	    if (!user) continue;
3125	    out.add(host ? `${user}@${host}` : user);
3126	  }
3127	  return out;
3128	}
