3130	/**
3131	 * Generate `CREATE USER … / GRANT …` for the source's APPLICATION accounts.
3132	 *
3133	 * The dump deliberately skips the `mysql` system schema (restoring it across
3134	 * engine versions corrupts the import), which silently left every application DB
3135	 * user behind: the data arrived but the app got access-denied. This closes that
3136	 * hole without reintroducing the system-schema problem.
3137	 *
3138	 * Password material NEVER enters this process: the script runs on the source and
3139	 * its stdout is redirected straight into a 0600 file on the target, which is
3140	 * applied with `mysql < file` and then shredded. `SHOW CREATE USER` preserves the
3141	 * existing hash (`IDENTIFIED WITH … AS '<hash>'` / `IDENTIFIED BY PASSWORD`), so
3142	 * application passwords keep working unchanged. `IF NOT EXISTS` makes a re-run
3143	 * idempotent instead of duplicating or resetting accounts.
3144	 *
3145	 * Every user/host pair is MYSQL_USER_RE / MYSQL_HOST_RE validated, and MySQL's
3146	 * own root/maintenance accounts are excluded before this is ever called.
3147	 */
3148	function mysqlGrantsScript(priv: string, accounts: { user: string; host: string }[]): string {
3149	  const specs = accounts.map((a) => `${a.user}:${a.host}`).join(" ");
3150	  return [
3151	    "export LC_ALL=C",
3152	    'PRIV="' + priv + '"',
3153	    "printf -- '-- application accounts migrated by Nxeon\\n'",
3154	    "for spec in " + specs + "; do",
3155	    "  u=${spec%%:*}",
3156	    "  h=${spec#*:}",
3157	    '  $PRIV mysql -N -B -e "SHOW CREATE USER \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/^CREATE USER /CREATE USER IF NOT EXISTS /\' -e \'s/$/;/\'',
3158	    '  $PRIV mysql -N -B -e "SHOW GRANTS FOR \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/$/;/\'',
3159	    "done",
3160	    "",
3161	  ].join("\n");
3162	}
