3167	/**
3168	 * Generating the web-server config removed one class of stale reference, but
3169	 * EVERYTHING ELSE is copied verbatim. In the field the old IP appeared in 21
3170	 * files — Apache vhosts under each home's `conf/web` dir, app config, systemd units,
3171	 * cron scripts, compose files, and connection strings like
3172	 * `redis://<old-ip>:6379`. Certificate paths are the same story: a mail server or
3173	 * a custom Node HTTPS listener pointing at
3174	 * `/etc/letsencrypt/live/<name>/fullchain.pem` breaks silently — or, as happened
3175	 * here, takes nginx down completely — when that path never came across.
3176	 *
3177	 * The governing rule is SCAN BROADLY, REWRITE NARROWLY. A blind find-and-replace
3178	 * across a copied tree is data corruption waiting to happen: the old IP and
3179	 * hostname legitimately appear inside database dumps (rewriting them silently
3180	 * edits the customer's data), log files, git objects, backups, archives and
3181	 * binaries. So the scan skips those entirely, and only an explicit allowlist of
3182	 * files the migration is itself responsible for is ever written to. Everything
3183	 * else is reported with file, line and matched value.
3184	 *
3185	 * We report the MATCHED VALUE, never the matched line: a hit on
3186	 * `postgres://user:password@<old-ip>/db` would otherwise put a live credential
3187	 * into the migration log. `grep -o` returns exactly the needle and nothing else.
3188	 */
3189	// Directory names never worth scanning — build output, dependency trees, VCS
3190	// internals, caches, logs and backups. Also the places a false-positive rewrite
3191	// would do the most damage.
3192	const SWEEP_EXCLUDE_DIRS = [
3193	  ".git", ".svn", ".hg", "node_modules", "vendor", "bower_components", ".cache", "cache",
3194	  "__pycache__", ".pytest_cache", "logs", "log", "backups", "backup", ".next", ".nuxt",
3195	  "dist", "build", "out", ".venv", "venv", "tmp", "temp", ".terraform", "storage",
3196	  "coverage", ".pnpm-store", ".yarn", "site-packages",
3197	];
3198	// File shapes that are DATA, ARCHIVES, MEDIA or KEY MATERIAL — never config.
3199	// `*.sql` / `*.dump` are the critical ones: they are customer data, and rewriting
3200	// an IP inside a dump silently corrupts the very thing we just migrated.
3201	const SWEEP_EXCLUDE_GLOBS = [
3202	  "*.sql", "*.dump", "*.bak", "*.gz", "*.zst", "*.bz2", "*.xz", "*.tar", "*.tgz", "*.zip",
3203	  "*.7z", "*.rar", "*.log", "*.log.*", "*.png", "*.jpg", "*.jpeg", "*.gif", "*.webp",
3204	  "*.svg", "*.ico", "*.pdf", "*.woff", "*.woff2", "*.ttf", "*.eot", "*.otf", "*.mp4",
3205	  "*.mp3", "*.avi", "*.mov", "*.so", "*.so.*", "*.a", "*.o", "*.pyc", "*.class", "*.jar",
3206	  "*.war", "*.bin", "*.exe", "*.dll", "*.db", "*.sqlite", "*.sqlite3", "*.pem", "*.key",
3207	  "*.crt", "*.csr", "*.p12", "*.pfx", "*.lock", "*.map", "*.min.js", "*.min.css",
3208	];
3209	const SWEEP_MAX_FILE_SIZE = "2M";
3210	const SWEEP_MAX_HITS = 200;
