3215	/**
3216	 * Build the read-only sweep. `dirs` are validated absolute paths and `needles`
3217	 * are validated IPv4 addresses / hostnames (both shell-inert charsets), and the
3218	 * script is written to the target over SFTP and run with `sh` rather than
3219	 * assembled in a shell — so there is no injection surface.
3220	 */
3221	function staleSweepScript(dirs: string[], needles: string[], work: string): string {
3222	  const pruneExpr = SWEEP_EXCLUDE_DIRS.map((d) => `-name ${d}`).join(" -o ");
3223	  const nameExcl = SWEEP_EXCLUDE_GLOBS.map((g) => `! -name '${g}'`).join(" ");
3224	  const needleArgs = needles.map((n) => `-e ${n}`).join(" ");
3225	  return [
3226	    "export LC_ALL=C",
3227	    'if command -v timeout >/dev/null 2>&1; then TO="timeout 120"; else TO=""; fi',
3228	    `LIST=${work}/stale-files.lst`,
3229	    // `grep -I` below skips binaries; the size cap and prune/exclude lists keep
3230	    // this bounded even on a large tree.
3231	    `find ${dirs.join(" ")} \\( -type d \\( ${pruneExpr} \\) -prune \\) -o ` +
3232	      `\\( -type f -size -${SWEEP_MAX_FILE_SIZE} ${nameExcl} -print0 \\) 2>/dev/null > "$LIST"`,
3233	    'if [ -s "$LIST" ]; then',
3234	    // -o prints ONLY the matched needle, so a matched line containing a password
3235	    // in a connection string never leaves the box. The needle pass is omitted
3236	    // entirely when there is nothing to look for; the certificate pass still runs.
3237	    ...(needles.length
3238	      ? [`  $TO xargs -0 -r grep -I -H -n -o -F ${needleArgs} -- < "$LIST" 2>/dev/null | head -n ${SWEEP_MAX_HITS} | awk '{print "HIT\\t" $0}'`]
3239	      : []),
3240	    `  $TO xargs -0 -r grep -I -H -n -o -E '/etc/letsencrypt/live/[A-Za-z0-9._-]+' -- < "$LIST" 2>/dev/null | head -n ${SWEEP_MAX_HITS} | awk '{print "CERTREF\\t" $0}'`,
3241	    "fi",
3242	    'rm -f "$LIST"',
3243	    "printf 'SWEEP_OK\\t1\\n'",
3244	    "",
3245	  ].join("\n");
3246	}
