3248	/** `path:line:value` — path and value charsets exclude `:`, so this split is exact. */
3249	function parseSweepHit(body: string): StaleHit | null {
3250	  const m = /^(\/[A-Za-z0-9._/-]{1,255}):(\d{1,9}):(.+)$/.exec(body);
3251	  if (!m) return null;
3252	  const file = m[1];
3253	  const line = Number(m[2]);
3254	  if (!validPath(file) || !Number.isInteger(line)) return null;
3255	  return { file, line, value: clean(m[3], 255) };
3256	}
