3405	    const portNum = Number(s?.proxyPort);
3406	    const proxyPort = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535 ? portNum : 0;
3407	    const root = typeof s?.root === "string" && validPath(s.root) ? s.root : "";
