3437	/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
3438	async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
3439	  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
