3452	/**
3453	 * Repoint migrated renewal profiles at THIS server. Without this, `certbot renew`
3454	 * keeps trying the old server's webroot (or its nginx/apache installer) and the
3455	 * migrated certificates quietly stop renewing about 60 days later. DNS-01
3456	 * profiles are left alone — their authenticator is already host-independent.
3457	 */
3458	const RENEWAL_FIX_SCRIPT = [
3459	  "n=0",
3460	  "for f in /etc/letsencrypt/renewal/*.conf; do",
3461	  '  [ -f "$f" ] || continue',
3462	  "  if grep -qE '^authenticator[[:space:]]*=[[:space:]]*dns' \"$f\"; then continue; fi",
3463	  "  sed -i -e 's|^authenticator[[:space:]]*=.*|authenticator = webroot|' " +
3464	    "-e 's|^installer[[:space:]]*=.*|installer = None|' " +
3465	    "-e 's|^webroot_path[[:space:]]*=.*|webroot_path = /var/www/html,|' \"$f\"",
3466	  "  awk 'BEGIN{m=0} /^\\[\\[webroot_map\\]\\]/{print; m=1; next} m==1 && /=/{sub(/=.*/, \"= /var/www/html\"); print; next} {print}' \"$f\" > \"$f.nx\" 2>/dev/null && mv \"$f.nx\" \"$f\"",
3467	  "  grep -q '^webroot_path' \"$f\" || printf 'webroot_path = /var/www/html,\\n' >> \"$f\"",
3468	  "  n=$((n+1))",
3469	  "done",
3470	  "printf 'RENEWALFIX %s\\n' \"$n\"",
3471	  "",
3472	].join("\n");
