3474	async function fixRenewalConfigs(conn: Client, sftp: SFTPWrapper, work: string): Promise<number> {
3475	  const p = `${work}/fix-renewal.sh`;
3476	  await sftpWrite(sftp, p, RENEWAL_FIX_SCRIPT).catch(() => {});
3477	  const r = await sh(conn, `sh ${p} 2>/dev/null`, SETUP_TIMEOUT_MS);
3478	  const m = /RENEWALFIX\s+(\d+)/.exec(r.stdout);
3479	  return m ? Number(m[1]) : 0;
