3487	/** HTTP-01 via webroot. `certName` fixes the /etc/letsencrypt/live/<name> directory. */
3488	async function issueHttp01(conn: Client, certName: string, domains: string[], email: string): Promise<{ ok: boolean; err: string }> {
3489	  const ds = [...new Set(domains.filter((d) => DOMAIN_RE.test(d)))].slice(0, 20);
