3499	/**
3500	 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
3501	 * wildcard. The token never appears in argv: it is written to a 0600 credentials
3502	 * file over SFTP and shredded immediately afterwards, success or failure.
3503	 */
3504	async function issueDns01(
3505	  conn: Client,
3506	  sftp: SFTPWrapper,
3507	  work: string,
3508	  token: string,
3509	  certName: string,
3510	  domains: string[],
3511	  email: string
3512	): Promise<{ ok: boolean; err: string }> {
3513	  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
3514	  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, ""))).slice(0, 20);
3515	  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
3516	  const ini = `${work}/cf-dns.ini`;
3517	  try {
3518	    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
3519	    await sh(conn, `chmod 600 ${ini}`);
3520	    const cmd =
3521	      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
3522	      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
3523	      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
3524	    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
3525	    if (await certExists(conn, certName)) return { ok: true, err: "" };
3526	    return { ok: false, err: tailOf(r, 2, 220) };
3527	  } finally {
3528	    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
3529	  }
3530	}
