3532	/**
3533	 * A wildcard covers exactly ONE label, so a multi-tenant app that also has a
3534	 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
3535	 * `*.example.com`. Return every base that needs its own wildcard.
3536	 */
3537	export function wildcardBasesFor(site: TargetSite): string[] {
3538	  const bases = new Set<string>();
3539	  if (site.wildcard) bases.add(site.wildcard);
3540	  for (const n of site.names) {
3541	    const parts = n.split(".");
3542	    if (parts.length < 3) continue;
3543	    const parent = parts.slice(1).join(".");
3544	    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
3545	  }
3546	  return [...bases].slice(0, 4);
3547	}
