51	  /**
52	   * Explicit opt-in to use an attached block-storage volume for Docker's stores
53	   * (`/var/lib/docker` + `/var/lib/containerd`). **Defaults to false.**
54	   *
55	   * Volumes are portable: the Volumes UI promises they can be attached to any of
56	   * the customer's running servers, and their data survives a server rebuild.
57	   * Mounting a system path on a volume silently ends that — the server can no
58	   * longer boot properly without it. So this is never inferred from free space;
59	   * the customer ticks a box in the wizard that says so in as many words. Stored
60	   * under Migration.items (an existing Json column) — no schema change.
61	   */
62	  useVolumeForDocker?: boolean;
63	};
