65	// The passwordless lift-and-shift plan, derived from the scan + selected paths and
66	// carried through Migration.items (secret-free). The worker re-validates every
67	// value against strict shell-inert allowlists before it is used in a command.
68	type MigrationPlan = {
69	  dbEngines: ("mysql" | "postgres")[];
70	  dockerVolumes: string[];
71	  composeDirs: string[];
72	  verifyPorts: number[];
73	  hasContainers: boolean;
74	  webServers: ("nginx" | "apache")[];
75	  runtimes: ("nodejs" | "python3")[];
76	};
