78	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
79	
80	export type MigrationDatabaseView = {
81	  engine: string;
82	  name: string;
83	  user: string;
84	};
85	
86	export type MigrationRow = {
87	  id: string;
88	  serverId: string;
89	  serverName: string | null;
90	  sourceHost: string;
91	  sourcePort: number;
92	  sourceUser: string;
93	  paths: string[];
94	  databases: MigrationDatabaseView[];
95	  status: string;
96	  progress: number;
97	  step: string | null;
98	  log: string | null;
99	  lastError: string | null;
100	  createdAt: string;
101	  finishedAt: string | null;
102	};
