104	// ---- Validation -------------------------------------------------------------
105	
106	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
107	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
108	// resolution; this only rejects obvious junk before we store anything.
109	const HOST_RE =
110	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
111	const DEFAULT_PATHS = ["/var/www", "/home"];
112	const MAX_PATHS = 40;
113	
114	function cleanPaths(paths: string[] | undefined): string[] {
115	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
116	    .map((p) => p.trim())
117	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
118	  // De-dupe while preserving order.
119	  return [...new Set(list)].slice(0, MAX_PATHS);
120	}
121	
122	// Docker volume names are shell-inert (docker's own charset) — the worker
123	// re-validates, but we only ever store well-formed names.
124	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
125	function isCopyableAbsPath(p: string): boolean {
126	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
127	}
128	
129	/**
130	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
131	 * of paths the customer chose to copy. Databases are auto-included whenever an
132	 * engine was detected (no password needed — the worker dumps via root's local
133	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
134	 * can install them on the target. Everything here is secret-free.
135	 */
136	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
137	  const empty: MigrationPlan = {
138	    dbEngines: [],
139	    dockerVolumes: [],
140	    composeDirs: [],
141	    verifyPorts: [],
142	    hasContainers: false,
143	    webServers: [],
144	    runtimes: [],
145	  };
146	  if (!scan || !scan.ok) return empty;
147	  const pathSet = new Set(selectedPaths);
148	
149	  // Auto-include every detected engine (dump passwordlessly via root local auth).
150	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
151	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
152	  );
153	
154	  const containers = scan.containers ?? [];
155	  // Named Docker volumes = container mounts that are NOT absolute host paths.
156	  const dockerVolumes = [
157	    ...new Set(
158	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
159	    ),
160	  ].slice(0, 60);
161	
162	  // Compose project dirs among the app dirs the customer is actually copying.
163	  const composeDirs = [
164	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
165	  ].slice(0, 40);
166	
167	  // Ports we will hold the migration accountable for. ONLY the customer's own
168	  // services — never the base operating system's.
169	  //
170	  // This used to be every listening port on the source except 22, so a stock
171	  // Debian box handed the customer `25` (exim4, installed by the distro and never
172	  // configured), `5355` (systemd-resolved's mDNS stub) and `53` as "not up on the
173	  // target yet — start the owning app/service". Those are not the customer's
174	  // software, were never part of what they asked to move, and cannot be started
175	  // by them in any meaningful sense. Seven of twenty-two action items in the
176	  // 2026-07-26 rehearsal were this noise, which is how a real action item gets
177	  // lost: a list that cries wolf is a list nobody reads to the end of.
178	  //
179	  // Filtering by PORT NUMBER would be the wrong fix — a customer really can run
180	  // their own mail server on 25. The honest discriminator is the OWNING PROCESS,
181	  // which the scan already captured, so a port is dropped only when the thing
182	  // listening on it is a distro daemon we did not migrate.
183	  const OS_DAEMONS =
184	    /^(systemd-resolve|systemd-resolved|systemd-network|exim4?|sendmail|postfix|rpcbind|rpc\.statd|avahi-daemon|cupsd|chronyd?|ntpd|dhclient|dhcpcd|named|dnsmasq|snapd|multipathd|master)$/i;
185	  const verifyPorts = [
186	    ...new Set(
187	      (scan.ports ?? [])
188	        .filter((p) => {
189	          if (!Number.isInteger(p.port) || p.port < 1 || p.port > 65535 || p.port === 22) return false;
190	          // No owning process recorded: keep it. An unknown is reported, never
191	          // silently dropped — that is the mistake this whole engine exists to
192	          // stop making.
193	          const proc = (p.proc || "").trim().toLowerCase();
194	          if (!proc) return true;
195	          return !OS_DAEMONS.test(proc);
196	        })
197	        .map((p) => p.port)
198	    ),
199	  ].slice(0, 60);
200	
201	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
202	
203	  // Web servers: match the owning process/service names, else default to nginx
204	  // when web roots exist (the overwhelmingly common case).
205	  const procBlob = [
206	    ...(scan.ports ?? []).map((p) => p.proc || ""),
207	    ...(scan.services ?? []).map((s) => s.name || ""),
208	  ]
209	    .join(" ")
210	    .toLowerCase();
211	  const webServers: ("nginx" | "apache")[] = [];
212	  if (/nginx/.test(procBlob)) webServers.push("nginx");
213	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
214	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
215	
216	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
217	  const runtimeBlob = [
218	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
219	    ...(scan.ports ?? []).map((p) => p.proc || ""),
220	  ]
221	    .join(" ")
222	    .toLowerCase();
223	  const runtimes: ("nodejs" | "python3")[] = [];
224	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
225	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
226	
227	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
228	}
229	
230	const GiB = 1024 ** 3;
231	
232	/** Working headroom the transfer needs while images load/unpack. Mirrors the
233	 *  engine's pre-flight allowance in worker/migrate-real.ts so the wizard's
234	 *  "will it fit?" answer and the worker's refusal can never disagree. */
235	const MIGRATION_HEADROOM_BYTES = 2 * GiB;
236	void MIGRATION_HEADROOM_BYTES; // kept for reference; the worker owns the headroom allowance
237	
238	/**
239	 * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
240	 * when a database engine was detected (databases are auto-included). Sizes come
241	 * from the read-only scan's human size labels; unknown-size items (custom folders,
242	 * Docker mounts) count as 0. Used both for the client storage panel and the
243	 * worker pre-flight — computed server-side here so the stored total is trusted.
244	 */
245	function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
246	  if (!scan || !scan.ok) return 0;
247	  const sizeByPath = new Map<string, number>();
248	  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
249	  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
250	  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
251	  let total = 0;
252	  for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
253	  // Databases are auto-included whenever an engine is present.
254	  const enginePresent = (scan.engines ?? []).some((e) => e.present);
255	  if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
256	  // CONTRACT — this is FILES ONLY (selected paths + the DB data-dir estimate).
257	  // It is stored as `items.totalBytes`, and the worker pre-flight reads it as
258	  // `fileBytes` and then adds the Docker image allowance + headroom ITSELF
259	  // (worker/migrate-real.ts). Adding Docker here as well made the engine count it
260	  // TWICE — a ~12 GB move was reported as needing 83.6 GB and refused. The wizard
261	  // displays the combined figure by computing its own file/Docker split
262	  // client-side; it never renders this value, so keep this files-only.
263	  return Math.round(total);
264	}
265	
266	/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
267	function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
268	  const o: Record<string, string> = {};
269	  for (const line of (stdout ?? "").split("\n")) {
270	    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
271	    if (!m) continue;
272	    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
273	  }
274	  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
275	  return {
276	    id: (o.ID ?? "").toLowerCase().slice(0, 32),
277	    versionId: (o.VERSION_ID ?? "").slice(0, 32),
278	    pretty: o.PRETTY_NAME ?? "",
279	  };
280	}
