282	/**
283	 * Validate a customer-named SOURCE host and resolve it to a vetted PUBLIC
284	 * address.
285	 *
286	 * This module's whole job is to SSH, from inside the platform, into a machine
287	 * whose address, username and password the customer types into a form. `HOST_RE`
288	 * checked only that the string looked like a host — so `10.20.0.137`,
289	 * `127.0.0.1` and the Proxmox host's own address all passed. That made the
290	 * migration wizard three things it was never meant to be:
291	 *
292	 *   - an internal PORT SCANNER of 10.20.0.0/24, which is every other customer's
293	 *     VPS, distinguishable because `scanSource` reports "couldn't sign in"
294	 *     (something is listening and speaking SSH) separately from "couldn't reach"
295	 *     (nothing there);
296	 *   - an SSH CREDENTIAL-STUFFING engine against those same machines, since the
297	 *     password is supplied per attempt;
298	 *   - a way to point it at the hypervisor and the platform's own loopback.
299	 *
300	 * A real migration source is always a public IP at another provider, so refusing
301	 * private / loopback / link-local / reserved targets costs a legitimate customer
302	 * nothing. `resolvePublicHost` (lib/tools/net-guard.ts) also resolves the name
303	 * itself and rejects if ANY A/AAAA record is private, which closes the DNS
304	 * rebinding variant — a name that answers public on our check and private on the
305	 * connect. The vetted address is returned so the caller can connect to the IP we
306	 * actually checked rather than re-resolving.
307	 */
308	async function vettedSourceHost(
309	  raw: string | undefined,
310	): Promise<{ host: string; address: string } | { error: string }> {
311	  const host = (raw ?? "").trim();
312	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
313	    return { error: "Enter a valid source host — an IP address or domain name." };
314	  }
315	  try {
316	    const resolved = await resolvePublicHost(host);
317	    return { host, address: resolved.addresses[0] ?? host };
318	  } catch (e) {
319	    if (e instanceof BlockedHostError) {
320	      return {
321	        error:
322	          `We can't migrate from ${host}: ${e.message} ` +
323	          `The source has to be a server reachable on the public internet — use its public IP address ` +
324	          `or a domain name that points at it, not a private/LAN address.`,
325	      };
326	    }
327	    return {
328	      error:
329	        `We couldn't look up ${host}. Check the spelling, or enter the source server's public IP address instead.`,
330	    };
331	  }
332	}
333	
334	async function ownedTargetServer(serverId: string) {
335	  const user = await requireUser();
336	  const server = await db.server.findUnique({ where: { id: serverId } });
337	  if (!server) throw new Error("Not found");
338	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
339	  return { user, server };
340	}
