342	function toRow(
343	  m: {
344	    id: string;
345	    serverId: string;
346	    sourceHost: string;
347	    sourcePort: number;
348	    sourceUser: string;
349	    items: unknown;
350	    status: string;
351	    progress: number;
352	    step: string | null;
353	    log: string | null;
354	    lastError: string | null;
355	    createdAt: Date;
356	    finishedAt: Date | null;
357	  },
358	  server: { hostname: string; label: string | null } | null
359	): MigrationRow {
360	  const items = (m.items ?? {}) as {
361	    paths?: string[];
362	    databases?: { engine?: string; name?: string; user?: string }[];
363	    dbEngines?: string[];
364	  };
365	  // Databases are now auto-included per detected engine (no per-DB list). For the
366	  // client view, surface one row per engine; fall back to any legacy per-DB list.
367	  const dbView: MigrationDatabaseView[] =
368	    Array.isArray(items.databases) && items.databases.length
369	      ? items.databases.map((d) => ({
370	          engine: String(d.engine ?? ""),
371	          name: String(d.name ?? ""),
372	          user: String(d.user ?? ""),
373	        }))
374	      : Array.isArray(items.dbEngines)
375	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
376	        : [];
377	  return {
378	    id: m.id,
379	    serverId: m.serverId,
380	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
381	    // caller resolves the server row and passes it in.
382	    serverName: server ? server.label || server.hostname : null,
383	    sourceHost: m.sourceHost,
384	    sourcePort: m.sourcePort,
385	    sourceUser: m.sourceUser,
386	    paths: Array.isArray(items.paths) ? items.paths : [],
387	    // Never expose any DB secret — dbView carries only non-sensitive fields.
388	    databases: dbView,
389	    status: m.status,
390	    progress: m.progress,
391	    step: m.step,
392	    log: m.log,
393	    lastError: m.lastError,
394	    createdAt: m.createdAt.toISOString(),
395	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
396	  };
397	}
