401	/**
402	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
403	 * ownership, validates the source connection details, encrypts every source
404	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
405	 * the new migration id; never returns any secret.
406	 */
407	export async function createMigration(
408	  input: CreateMigrationInput
409	): Promise<{ error?: string; id?: string }> {
410	  const { user, server } = await ownedTargetServer(input.serverId);
411	
412	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
413	  // credential-stuffing the wizard against arbitrary source hosts.
414	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
415	  if (!rl.ok) {
416	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
417	  }
418	
419	  // Same public-address gate as scanSource — the worker will SSH here.
420	  const vetted = await vettedSourceHost(input.sourceHost);
421	  if ("error" in vetted) return { error: vetted.error };
422	  const host = vetted.host;
423	
424	  const port = input.sourcePort ?? 22;
425	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
426	    return { error: "SSH port must be between 1 and 65535." };
427	  }
428	
429	  const sourceUser = (input.sourceUser ?? "root").trim();
430	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
431	    return { error: "Enter the SSH username on the source server." };
432	  }
433	
434	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
435	    return { error: "Enter the SSH password for the source server." };
436	  }
437	
438	  const paths = cleanPaths(input.paths);
439	
440	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
441	  // Databases are auto-included when an engine is detected — no DB password is
442	  // ever collected; the worker dumps via root's local socket/peer auth.
443	  const plan = derivePlan(input.scan, paths);
444	
445	  // Persist the (secret-free) detection snapshot alongside the plan so the
446	  // migration is traceable back to what auto-detection found. Reusing items
447	  // avoids a schema change (Migration.items is a Json column).
448	  const scanSnapshot =
449	    input.scan && input.scan.ok
450	      ? {
451	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
452	          homes: input.scan.homes?.slice(0, 40) ?? [],
453	          databases: input.scan.databases?.slice(0, 60) ?? [],
454	          engines: input.scan.engines ?? [],
455	          // Exact engine variant + version — lets the worker install the MATCHING
456	          // engine on the target for a clean same-engine restore.
457	          dbEngines: input.scan.dbEngines ?? [],
458	          // Running-app discovery — informational, secret-free, for traceability.
459	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
460	          containers: input.scan.containers?.slice(0, 30) ?? [],
461	          ports: input.scan.ports?.slice(0, 60) ?? [],
462	          services: input.scan.services?.slice(0, 30) ?? [],
463	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
464	          // and the worker pre-flight).
465	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
466	          sourceOs: input.scan.sourceOs ?? null,
467	          sourceArch: input.scan.sourceArch ?? null,
468	          synthetic: !!input.scan.synthetic,
469	        }
470	      : undefined;
471	
472	  // Trusted server-side total of what will be migrated (bytes) — carried through
473	  // items so the worker's pre-flight guard can compare it to target free disk
474	  // without re-scanning. No schema change: Migration.items is a Json column.
475	  const totalBytes = selectedMigrationBytes(input.scan, paths);
476	
477	  const items = {
478	    paths,
479	    dbEngines: plan.dbEngines,
480	    dockerVolumes: plan.dockerVolumes,
481	    composeDirs: plan.composeDirs,
482	    verifyPorts: plan.verifyPorts,
483	    hasContainers: plan.hasContainers,
484	    webServers: plan.webServers,
485	    runtimes: plan.runtimes,
486	    totalBytes,
487	    // Explicit consent only — coerced to a real boolean so nothing else can ride
488	    // in on this field, and only ever true when the customer ticked the box.
489	    useVolumeForDocker: input.useVolumeForDocker === true,
490	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
491	  };
492	
493	  const migration = await db.migration.create({
494	    data: {
495	      userId: user.id,
496	      serverId: server.id,
497	      sourceHost: host,
498	      sourcePort: port,
499	      sourceUser,
500	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
501	      items,
502	      status: "PENDING",
503	      progress: 0,
504	      step: "Queued",
505	    },
506	  });
507	
508	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
509	  // traceability); the handler loads everything else from payload.migrationId.
510	  await db.job.create({
511	    data: {
512	      type: "MIGRATE",
513	      serverId: server.id,
514	      payload: { migrationId: migration.id },
515	    },
516	  });
517	
518	  await db.auditLog.create({
519	    data: {
520	      userId: user.id,
521	      action: "migration.create",
522	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
523	    },
524	  });
525	
526	  revalidatePath("/dashboard/migrate");
527	  return { id: migration.id };
528	}
