530	/**
531	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
532	 * caller owns the TARGET server (authz + a stricter rate limit than create),
533	 * validates the source connection details, then SSHes into the source and
534	 * inventories web roots / home directories / databases — never writing anything
535	 * on the source and never persisting the supplied credentials.
536	 *
537	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
538	 * are NOT stored anywhere; the client re-supplies them to createMigration once
539	 * the customer confirms what to move. Returns a secret-free ScanResult.
540	 *
541	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
542	 * a real SSH connection, so staging stays fully self-contained.
543	 */
544	export async function scanSource(input: {
545	  serverId: string;
546	  sourceHost: string;
547	  sourcePort?: number;
548	  sourceUser?: string;
549	  sourcePassword: string;
550	  dbUser?: string;
551	  dbPassword?: string;
552	}): Promise<{ error?: string; scan?: ScanResult }> {
553	  const { user } = await ownedTargetServer(input.serverId);
554	
555	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
556	  // than migration creation to stop the wizard being used to probe hosts.
557	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
558	  if (!rl.ok) {
559	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
560	  }
561	
562	  // Refuse private / loopback / reserved targets BEFORE anything is logged or
563	  // connected to. See vettedSourceHost: without this the wizard is an internal
564	  // port scanner and SSH credential-stuffer aimed at every other customer's VM.
565	  const vetted = await vettedSourceHost(input.sourceHost);
566	  if ("error" in vetted) return { error: vetted.error };
567	  const host = vetted.host;
568	  const port = input.sourcePort ?? 22;
569	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
570	    return { error: "SSH port must be between 1 and 65535." };
571	  }
572	  const sourceUser = (input.sourceUser ?? "root").trim();
573	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
574	    return { error: "Enter the SSH username on the source server." };
575	  }
576	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
577	    return { error: "Enter the SSH password for the source server." };
578	  }
579	
580	  await db.auditLog.create({
581	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
582	  }).catch(() => {});
583	
584	  // SANDBOX: never touch the outside world — hand back synthetic detection.
585	  if (SANDBOX) {
586	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
587	  }
588	
589	  // Hard overall timeout so a slow/hostile source can't hang the request.
590	  const HARD_TIMEOUT_MS = 90_000;
591	  try {
592	    const scan = await Promise.race<ScanResult>([
593	      detectSource({
594	        // The ADDRESS we vetted, not the name — a name can resolve public for
595	        // our check and private for the connect (DNS rebinding).
596	        host: vetted.address,
597	        port,
598	        user: sourceUser,
599	        password: input.sourcePassword,
600	        dbUser: input.dbUser?.trim() || undefined,
601	        dbPassword: input.dbPassword || undefined,
602	      }),
603	      new Promise<ScanResult>((_, reject) =>
604	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
605	      ),
606	    ]);
607	    return { scan };
608	  } catch (e: any) {
609	    const msg = `${e?.message ?? e}`;
610	    // Map the common connection failures to friendly, non-leaky copy.
611	    if (/authentication|denied|password/i.test(msg)) {
612	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
613	    }
614	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
615	      return { error: "Couldn't reach the source server — check the host and SSH port." };
616	    }
617	    return { error: "We couldn't scan that server. Double-check the details and try again." };
618	  }
619	}
