621	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
622	
623	export type TargetInfo = {
624	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
625	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
626	  os: { id: string; versionId: string; pretty: string } | null;
627	  arch: string | null;
628	  /**
629	   * Capacity of the LARGEST attached-but-unformatted block device (a volume the
630	   * customer added but hasn't used yet), or null if there isn't one.
631	   *
632	   * This is capacity that is available **only if the customer chooses to use it**
633	   * — the engine can format it and relocate the container stores onto it, but it
634	   * never does so on its own (see `useVolumeForDocker`). Volumes are portable
635	   * add-on storage, and mounting a system path on one makes it undetachable, so
636	   * the wizard presents this as an opt-in, not as free space.
637	   *
638	   * The LARGEST, not the sum: separate volumes are separate filesystems and the
639	   * engine uses exactly one. They are deliberately never combined into an LVM
640	   * pool — that would weld them together and destroy the portability of all of
641	   * them at once.
642	   */
643	  spareDiskBytes?: number | null;
644	  /**
645	   * How many unused volumes are attached. 2+ means the panel should say that only
646	   * the largest can be used, so the customer isn't left expecting them to add up.
647	   */
648	  spareDiskCount?: number | null;
649	};
650	
651	/**
652	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
653	 * space and OS/architecture, so the wizard can show the storage headroom and the
654	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
655	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
656	 *
657	 * Failure is graceful: if the server is unreachable or df can't be parsed we
658	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
659	 * migration with a soft warning rather than a hard block). OS falls back to the
660	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
661	 */
662	export async function targetDiskFree(
663	  serverId: string
664	): Promise<{ error?: string; info?: TargetInfo }> {
665	  const { server } = await ownedTargetServer(serverId);
666	
667	  // OS fallback from the known OS template (works even if the box is unreachable).
668	  const tmpl = await db.osTemplate
669	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
670	    .catch(() => null);
671	  const osFallback = tmpl
672	    ? {
673	        id: (tmpl.family || "linux").toLowerCase(),
674	        versionId: tmpl.version || "",
675	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
676	      }
677	    : null;
678	
679	  if (SANDBOX) {
680	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
681	    return {
682	      info: {
683	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
684	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
685	        arch: "x86_64",
686	      },
687	    };
688	  }
689	
690	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
691	  const full = await db.server.findUnique({
692	    where: { id: server.id },
693	    include: { dedicatedIp: true },
694	  });
695	
696	  try {
697	    const info = await withServerSsh(full as any, async (conn) => {
698	      // Root filesystem size/used/avail in bytes.
699	      const dfr = await exec(
700	        conn,
701	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
702	        QUICK_TIMEOUT_MS
703	      );
704	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
705	      let disk: TargetInfo["disk"] = null;
706	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
707	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
708	      }
709	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
710	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
711	      const osr = await exec(
712	        conn,
713	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
714	        QUICK_TIMEOUT_MS
715	      ).catch(() => ({ stdout: "" }) as any);
716	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
717	      // Attached-but-unformatted disks (unused volumes the customer added).
718	      // Read-only probe, and it mirrors the engine's qualification bar exactly so
719	      // the panel can never promise space the engine would refuse to touch: a
720	      // disk counts only when nothing in its tree has a filesystem or mount, it
721	      // has no children, nothing holds it, `blkid` finds no signature at all,
722	      // and it is at least the engine's 4 GiB floor.
723	      let spareDiskBytes: number | null = null;
724	      let spareDiskCount: number | null = null;
725	      try {
726	        const lb = await exec(
727	          conn,
728	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
729	            "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
730	            "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
731	            "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
732	            "blkid /dev/$d >/dev/null 2>&1 && continue; " +
733	            "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
734	            "[ -z \"$sz\" ] && continue; " +
735	            "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
736	          QUICK_TIMEOUT_MS
737	        );
738	        const sizes = ((lb.stdout as string) || "")
739	          .split("\n")
740	          .map((s) => Number(s.trim()))
741	          .filter((n) => Number.isFinite(n) && n > 0);
742	        if (sizes.length) {
743	          // The LARGEST, never the sum — the engine uses exactly one volume and
744	          // does not combine them, so summing would promise space that no single
745	          // filesystem will ever have. The count lets the panel say so plainly.
746	          spareDiskCount = sizes.length;
747	          spareDiskBytes = Math.max(...sizes);
748	        }
749	      } catch {
750	        /* best-effort: absence just means we report root-only free space */
751	      }
752	      return { disk, os, arch: arch ?? "x86_64", spareDiskBytes, spareDiskCount };
753	    });
754	    return { info };
755	  } catch {
756	    // Unreachable / probe error → soft warning (no hard block).
757	    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
758	  }
759	}
