761	/** The current user's migrations, newest first, WITHOUT any decrypted secrets. */
762	export async function listMigrations(): Promise<MigrationRow[]> {
763	  const user = await requireUser();
764	  const rows = await db.migration.findMany({
765	    where: { userId: user.id },
766	    orderBy: { createdAt: "desc" },
767	  });
768	  const serverIds = [...new Set(rows.map((r) => r.serverId))];
769	  const servers = await db.server.findMany({
770	    where: { id: { in: serverIds } },
771	    select: { id: true, hostname: true, label: true },
772	  });
773	  const byId = new Map(servers.map((s) => [s.id, s]));
774	  return rows.map((m) => toRow(m, byId.get(m.serverId) ?? null));
775	}
