793	// ---- Post-migration DNS cutover --------------------------------------------
794	
795	/**
796	 * A domain we can offer to repoint after a migration, plus where we got it from
797	 * (shown in the UI so the customer knows why it's listed).
798	 */
799	export type DnsCandidate = {
800	  host: string;
801	  source: "registered" | "website" | "scan";
802	};
803	
804	export type MigrationDnsInfo = {
805	  error?: string;
806	  targetIp?: string | null;
807	  targetName?: string | null;
808	  candidates?: DnsCandidate[];
809	  cloudflareConnected?: boolean;
810	};
811	
812	/** Pull a hostname out of a path like `/var/www/example.com` / `/home/example.com`. */
813	function hostnameFromPath(path: string): string | null {
814	  const leaf = String(path ?? "").split("/").filter(Boolean).pop() ?? "";
815	  const h = leaf.toLowerCase().replace(/^www\./, "");
816	  return cleanHostname(h);
817	}
818	
819	/**
820	 * Candidate domains to point at the migration's target server, cheapest source
821	 * first. Ownership-checked (the migration must be the caller's).
822	 *
823	 *   1. `Domain` rows — domains the customer registered with us.
824	 *   2. Websites already configured on the target server.
825	 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
826	 *      — web-root folders are conventionally named after the vhost. The snapshot
827	 *      does not record nginx/apache `server_name` values, so this is a best-effort
828	 *      read of what was already captured; we never re-scan the source.
829	 */
830	export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
831	  const user = await requireUser();
832	
833	  const m = await db.migration.findUnique({ where: { id: migrationId } });
834	  if (!m) return { error: "Migration not found." };
835	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
836	
837	  const server = await db.server.findUnique({
838	    where: { id: m.serverId },
839	    select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
840	  });
841	
842	  const seen = new Set<string>();
843	  const candidates: DnsCandidate[] = [];
844	  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
845	    const host = cleanHostname(raw ?? "");
846	    if (!host || seen.has(host)) return;
847	    seen.add(host);
848	    candidates.push({ host, source });
849	  };
850	
851	  const domains = await db.domain.findMany({
852	    where: { userId: m.userId },
853	    select: { name: true },
854	    orderBy: { name: "asc" },
855	    take: 50,
856	  });
857	  for (const d of domains) push(d.name, "registered");
858	
859	  const sites = await db.website.findMany({
860	    where: { serverId: m.serverId },
861	    select: { domain: true },
862	    take: 50,
863	  });
864	  for (const s of sites) push(s.domain, "website");
865	
866	  // Only what the scan already stored — no new source-scanning here.
867	  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
868	  for (const w of items.scan?.webRoots ?? []) {
869	    if (w?.path) push(hostnameFromPath(w.path), "scan");
870	  }
871	
872	  return {
873	    targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
874	    targetName: server ? server.label || server.hostname : null,
875	    candidates: candidates.slice(0, 40),
876	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
877	  };
878	}
879	
880	/**
881	 * Point one hostname at the migration's TARGET server by upserting an A record in
882	 * the customer's Cloudflare zone — the last manual step of an otherwise one-click
883	 * migration.
884	 *
885	 * Guards: requireUser + migration ownership, rate-limited, and the hostname is
886	 * re-validated server-side (`cleanHostname` inside pointHostnameToIp) because
887	 * this one legitimately comes from customer input (the "enter a domain" box).
888	 * The record is DNS-only (proxied=false) so the name resolves to the server
889	 * itself and Let's Encrypt HTTP-01 validation can succeed there.
890	 */
891	export async function pointMigrationDns(
892	  migrationId: string,
893	  hostname: string
894	): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
895	  const user = await requireUser();
896	
897	  const m = await db.migration.findUnique({ where: { id: migrationId } });
898	  if (!m) return { ok: false, error: "Migration not found." };
899	  if (m.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Not your migration." };
900	
901	  const rl = checkRateLimit(`migrate:dns:${user.id}`, { max: 20, windowMs: 60_000 });
902	  if (!rl.ok) return { ok: false, error: `Too many requests — retry in ${rl.retryAfterSec}s.` };
903	
904	  const server = await db.server.findUnique({
905	    where: { id: m.serverId },
906	    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
907	  });
908	  const ip = server?.dedicatedIp?.address ?? server?.ipAddress ?? null;
909	  if (!ip) {
910	    return { ok: false, error: "Your new server doesn't have a public IP yet — try again shortly." };
911	  }
912	
913	  const res = await pointHostnameToIp({
914	    user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
915	    hostname,
916	    ip,
917	  });
918	  if (!res.ok) return { ok: false, error: res.error };
919	
920	  await db.auditLog.create({
921	    data: {
922	      userId: user.id,
923	      action: "migration.dns",
924	      detail: `${res.hostname} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
925	    },
926	  });
927	
928	  return {
929	    ok: true,
930	    message: res.simulated
931	      ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). Nothing was sent to Cloudflare.`
932	      : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). It can take a few minutes for visitors to see the new server.`,
933	  };
934	}
