60	 *   - engine  : "mysql" (the MySQL/MariaDB family) or "postgres".
61	 *   - variant : "mysql" = Oracle MySQL, "mariadb" = MariaDB, null = couldn't tell
62	 *               (or N/A for postgres).
63	 *   - version : detected major(.minor), e.g. "8.0" (MySQL), "10.11" (MariaDB),
