328	/**
329	 * True when a reference cannot be pulled from a public registry — i.e. it is a
330	 * LOCALLY-BUILT tag. A registry host is the first `/`-segment when it contains a
331	 * `.` (a domain) or a `:` (a host:port), or is exactly `localhost`. Everything
332	 * else with a `/` is either Docker Hub `namespace/name` OR a local build tag and
333	 * we cannot tell them apart by name alone — so we treat it as local (a save/load
334	 * always works; a wrong pull guess leaves the container dead). A bare
335	 * `name[:tag]` with no `/` is a Docker Hub library image → pullable.
336	 */
337	export function isLocalImageRef(ref: string): boolean {
338	  const bare = ref.split("@")[0];
339	  const slash = bare.indexOf("/");
340	  if (slash < 0) return false; // library image, e.g. `redis:7-alpine`
341	  const head = bare.slice(0, slash);
342	  if (head === "localhost") return true;
343	  return !(head.includes(".") || head.includes(":"));
344	}
345	/** A hostname we would put in a generated vhost (lowercased, wildcard stripped). */
346	export function normalizeDomain(raw: string): string | null {
347	  let h = cleanText(raw ?? "", 253).toLowerCase().replace(/^\*\./, "").replace(/\.$/, "");
348	  h = h.replace(/^["']|["']$/g, "");
349	  if (!h || h.length > 253) return null;
350	  if (h === "localhost" || h === "_" || h === "default_server") return null;
351	  if (!DOMAIN_RE.test(h)) return null;
352	  // Reject bare TLD-ish and numeric-only labels (an IP is not a vhost name).
353	  if (/^\d+(\.\d+)*$/.test(h)) return null;
354	  const tld = h.slice(h.lastIndexOf(".") + 1);
355	  if (tld.length < 2 || /\d/.test(tld)) return null;
356	  return h;
357	}
