359	/** Collapse duplicate slashes and strip a trailing slash from a du-emitted path. */
360	function normalizeRemotePath(p: string): string {
361	  const collapsed = (p ?? "").replace(/\/{2,}/g, "/").replace(/\/+$/, "");
362	  return collapsed || "/";
363	}
