365	// ---- SSH plumbing (same shape as migrate-real.ts) -------------------------
366	function execRemote(
367	  conn: Client,
368	  cmd: string,
369	  timeoutMs: number
370	): Promise<{ code: number; stdout: string; stderr: string }> {
371	  return new Promise((resolve, reject) => {
372	    conn.exec(cmd, (err, stream: ClientChannel) => {
373	      if (err) return reject(err);
374	      let stdout = "";
375	      let stderr = "";
376	      const timer = setTimeout(() => {
377	        try {
378	          stream.close();
379	        } catch {
380	          /* ignore */
381	        }
382	        reject(new Error("remote command timed out"));
383	      }, timeoutMs);
384	      stream
385	        .on("close", (code: number) => {
386	          clearTimeout(timer);
387	          resolve({ code: code ?? 0, stdout, stderr });
388	        })
389	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
390	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
391	    });
392	  });
393	}
394	
