412	        }
413	        reject(new Error("remote command timed out"));
414	      }, timeoutMs);
415	      stream
416	        .on("close", (code: number) => {
417	          clearTimeout(timer);
418	          resolve({ code: code ?? 0, stdout, stderr });
419	        })
420	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
421	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
