427	function connectSource(input: DetectInput): Promise<Client> {
428	  return new Promise((resolve, reject) => {
429	    const conn = new Client();
430	    conn.on("ready", () => resolve(conn));
431	    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
432	    conn.connect({
433	      host: input.host,
434	      port: input.port,
435	      username: input.user,
436	      password: input.password,
437	      readyTimeout: CONNECT_TIMEOUT_MS,
438	      // Password-only: never offer a local key to the untrusted source host.
439	      tryKeyboard: false,
440	    });
441	  });
442	}
