445	function humanBytes(n: number): string {
446	  if (!Number.isFinite(n) || n <= 0) return "0 B";
447	  const units = ["B", "KB", "MB", "GB", "TB"];
448	  let i = 0;
449	  let v = n;
450	  while (v >= 1024 && i < units.length - 1) {
451	    v /= 1024;
452	    i++;
453	  }
454	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
455	}
