457	/**
458	 * The read-only probe script. Deliberately input-free: the only variable parts
459	 * are constant shell globs expanded by the REMOTE shell, so there is no
460	 * injection surface. POSIX-sh only (works under `sh` or `bash`).
461	 */
462	// NOTE: authored as a plain string (not a template literal) so shell `${...}`
463	// parameter expansions can never collide with JS `${}` interpolation. Any
464	// trailing/duplicate slashes in emitted paths are normalized in JS below.
465	const SCAN_SCRIPT = [
466	  "export LC_ALL=C",
467	  'if command -v timeout >/dev/null 2>&1; then TO="timeout 25"; else TO=""; fi',
468	  "emit_web() {",
469	  "  d=$1",
470	  '  [ -d "$d" ] || return 0',
471	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1)',
472	  '  [ -n "$sz" ] || sz=\'?\'',
473	  "  t=unknown",
474	  '  if [ -f "$d/wp-config.php" ]; then t=wordpress',
475	  '  elif [ -f "$d/artisan" ]; then t=laravel',
476	  '  elif [ -f "$d/manage.py" ]; then t=django',
477	  '  elif [ -f "$d/package.json" ]; then t=node',
478	  '  elif [ -f "$d/composer.json" ]; then t=php',
479	  "  else",
480	  '    for f in "$d"/*.php; do [ -e "$f" ] && { t=php; break; }; done',
481	  "  fi",
482	  "  printf 'WEB\\t%s\\t%s\\t%s\\n' \"$t\" \"$sz\" \"$d\"",
483	  "}",
484	  // Emit a candidate app directory OUTSIDE the web roots (a process cwd or a
485	  // signature-bearing dir). $1=runtime hint, $2=dir. Read-only: du + [ -f ] tests
486	  // only. seen_cwd de-dups within a shell to avoid repeated du on the same dir.
487	  "seen_cwd=' '",
488	  "emit_appdir() {",
489	  "  rt=$1; d=$2",
490	  '  [ -d "$d" ] || return 0',
491	  '  case "$d" in /|/usr|/usr/*|/bin|/sbin|/lib|/lib/*|/lib64*|/etc|/etc/*|/proc*|/sys*|/dev*|/run*|/tmp|/tmp/*|/var/lib/docker*|/snap*) return 0;; esac',
492	  '  case "$seen_cwd" in *" $d "*) return 0;; esac',
493	  '  seen_cwd="$seen_cwd$d "',
494	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
495	  "  sig=unknown",
496	  '  if [ -f "$d/wp-config.php" ]; then sig=wordpress',
497	  '  elif [ -f "$d/artisan" ]; then sig=laravel',
498	  '  elif [ -f "$d/manage.py" ]; then sig=django',
499	  '  elif [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ]; then sig=compose',
500	  '  elif [ -f "$d/requirements.txt" ]; then sig=python',
501	  '  elif [ -f "$d/package.json" ]; then sig=node',
502	  '  elif [ -f "$d/composer.json" ]; then sig=php',
503	  '  elif [ -d "$d/.git" ]; then sig=gitrepo',
504	  "  fi",
505	  "  printf 'APPDIR\\t%s\\t%s\\t%s\\t%s\\n' \"$rt\" \"$sig\" \"$sz\" \"$d\"",
506	  "}",
507	  'for d in /var/www/html /usr/share/nginx/html /var/www /srv/www; do emit_web "$d"; done',
508	  'for d in /var/www/*/ /srv/www/*/ /home/*/public_html; do emit_web "$d"; done',
509	  "for d in /home/*/; do",
510	  '  [ -d "$d" ] || continue',
511	  '  sz=$($TO du -shx "$d" 2>/dev/null | cut -f1); [ -n "$sz" ] || sz=\'?\'',
512	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" \"$d\"",
513	  "done",
514	  "if [ -d /root ]; then",
515	  "  sz=$($TO du -shx /root 2>/dev/null | cut -f1); [ -n \"$sz\" ] || sz='?'",
516	  "  printf 'HOME\\t%s\\t%s\\n' \"$sz\" /root",
517	  "fi",
518	  "mp=0; ml=0; pp=0; pl=0",
519	  "{ command -v mysqld >/dev/null 2>&1 || command -v mariadbd >/dev/null 2>&1 || command -v mysql >/dev/null 2>&1 || [ -d /var/lib/mysql ]; } && mp=1",
520	  "{ command -v pg_dump >/dev/null 2>&1 || command -v psql >/dev/null 2>&1 || [ -d /var/lib/postgresql ]; } && pp=1",
521	  "ports=$( (ss -H -lnt 2>/dev/null || netstat -lnt 2>/dev/null) )",
522	  "printf '%s\\n' \"$ports\" | grep -q ':3306[^0-9]' && ml=1",
523	  "printf '%s\\n' \"$ports\" | grep -q ':5432[^0-9]' && pl=1",
524	  "printf 'ENGINE\\tmysql\\t%s\\t%s\\n' \"$mp\" \"$ml\"",
525	  "printf 'ENGINE\\tpostgres\\t%s\\t%s\\n' \"$pp\" \"$pl\"",
526	  // ---- DB engine variant + version. Read-only: only the client's `--version`
527	  // banner (no DB connection). The banner says "MariaDB" for MariaDB; Oracle MySQL
528	  // omits it. Version parsing happens in JS. $TO-bounded, no interpolation. --
529	  'if [ "$mp" = 1 ]; then',
530	  "  mv=''",
531	  "  if command -v mariadb >/dev/null 2>&1; then mv=$($TO mariadb --version 2>/dev/null | head -n1)",
532	  "  elif command -v mysql >/dev/null 2>&1; then mv=$($TO mysql --version 2>/dev/null | head -n1)",
533	  "  elif command -v mariadbd >/dev/null 2>&1; then mv=$($TO mariadbd --version 2>/dev/null | head -n1)",
534	  "  elif command -v mysqld >/dev/null 2>&1; then mv=$($TO mysqld --version 2>/dev/null | head -n1)",
535	  "  fi",
536	  "  printf 'DBVER\\tmysql\\t%s\\n' \"$mv\"",
537	  "fi",
538	  'if [ "$pp" = 1 ]; then',
539	  "  pv=''",
540	  "  if command -v psql >/dev/null 2>&1; then pv=$($TO psql --version 2>/dev/null | head -n1)",
541	  "  elif command -v pg_config >/dev/null 2>&1; then pv=$($TO pg_config --version 2>/dev/null | head -n1)",
542	  "  fi",
543	  "  printf 'DBVER\\tpostgres\\t%s\\n' \"$pv\"",
544	  "fi",
545	  // ---- DB data-dir size estimate (bytes). Only probed when the engine is
546	  // present. Constant paths, read-only `du -sbx`, $TO-bounded — no injection. --
547	  'if [ "$mp" = 1 ] && [ -d /var/lib/mysql ]; then',
548	  "  mb=$($TO du -sbx /var/lib/mysql 2>/dev/null | cut -f1); [ -n \"$mb\" ] || mb=0",
549	  "  printf 'DBSIZE\\tmysql\\t%s\\n' \"$mb\"",
550	  "fi",
551	  'if [ "$pp" = 1 ] && [ -d /var/lib/postgresql ]; then',
552	  "  pb=$($TO du -sbx /var/lib/postgresql 2>/dev/null | cut -f1); [ -n \"$pb\" ] || pb=0",
553	  "  printf 'DBSIZE\\tpostgres\\t%s\\n' \"$pb\"",
554	  "fi",
555	  // ---- OS / CPU architecture (read-only). /etc/os-release is GREPPED, never
556	  // sourced (the source is untrusted — sourcing could execute code); values are
557	  // re-validated + bounded in JS. `uname -m` for the arch. --
558	  'arch=$(uname -m 2>/dev/null); [ -n "$arch" ] || arch=unknown',
559	  "printf 'ARCH\\t%s\\n' \"$arch\"",
560	  "if [ -r /etc/os-release ]; then",
561	  "  grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null | head -n 20 | while IFS= read -r orl; do",
562	  "    printf 'OSREL\\t%s\\n' \"$orl\"",
563	  "  done",
564	  "fi",
565	  // ---- Running Docker containers (name/image/ports/mounts). Read-only `docker ps`
566	  // only; wrapped in $TO so an unresponsive daemon can't hang the probe. Cap 30. --
567	  "if command -v docker >/dev/null 2>&1; then",
568	  "  $TO docker ps --no-trunc --format '{{.Names}}|{{.Image}}|{{.Ports}}|{{.Mounts}}' 2>/dev/null | head -n 30 | while IFS= read -r dl; do",
569	  "    [ -n \"$dl\" ] && printf 'DOCKER\\t%s\\n' \"$dl\"",
570	  "  done",
571	  // ---- Docker IMAGES + sizes. The migration has to carry locally-built images
572	  // across (docker save/load) and has to budget disk for pulls/loads/build cache;
573	  // both need this list. Read-only `docker images`, $TO-bounded, capped at 100. --
574	  "  $TO docker images --format '{{.Repository}}:{{.Tag}}|{{.Size}}' 2>/dev/null | head -n 100 | while IFS= read -r ml; do",
575	  "    [ -n \"$ml\" ] && printf 'IMAGE\\t%s\\n' \"$ml\"",
576	  "  done",
577	  // Named-volume bytes: they land under the target's Docker data root and so
578	  // compete for the SAME disk as images/build cache.
579	  "  if [ -d /var/lib/docker/volumes ]; then",
580	  "    dvb=$($TO du -sbx /var/lib/docker/volumes 2>/dev/null | cut -f1); [ -n \"$dvb\" ] || dvb=0",
