585	  // trees (grep) to learn (a) that they exist and (b) which domains the site
586	  // actually answers on, so the new server can serve the same names instead of
587	  // the stock "Welcome to nginx" page. Constant paths + constant patterns. --
588	  "if [ -d /etc/nginx ]; then",
589	  "  printf 'WEBCFG\\tnginx\\n'",
590	  "  $TO grep -rhoE 'server_name[[:space:]]+[^;]+' /etc/nginx 2>/dev/null | head -n 60 | while IFS= read -r sn; do",
591	  "    printf 'SRVNAME\\t%s\\n' \"$sn\"",
592	  "  done",
593	  "fi",
594	  "if [ -d /etc/apache2 ]; then printf 'WEBCFG\\tapache2\\n'; fi",
595	  "if [ -d /etc/httpd ]; then printf 'WEBCFG\\thttpd\\n'; fi",
596	  "if [ -d /etc/apache2 ] || [ -d /etc/httpd ]; then",
597	  "  $TO grep -rhoE '(ServerName|ServerAlias)[[:space:]]+[^[:space:]]+' /etc/apache2 /etc/httpd 2>/dev/null | head -n 60 | while IFS= read -r sn; do",
598	  "    printf 'SRVNAME\\t%s\\n' \"$sn\"",
599	  "  done",
600	  "fi",
601	  // ---- Existing TLS certificates (directory NAMES only — never key material). --
602	  "if [ -d /etc/letsencrypt/live ]; then",
603	  "  for led in /etc/letsencrypt/live/*/; do",
604	  '    [ -d "$led" ] || continue',
605	  '    leb=${led%/}; leb=${leb##*/}',
606	  '    [ -n "$leb" ] && printf \'TLSCERT\\t%s\\n\' "$leb"',
607	  "  done",
608	  "fi",
609	  // ---- Scheduled work that a lift-and-shift otherwise leaves behind. Count only. --
610	  "cronn=0",
611	  "for crd in /var/spool/cron/crontabs /var/spool/cron /etc/cron.d; do",
612	  '  [ -d "$crd" ] || continue',
613	  '  crk=$(ls -1 "$crd" 2>/dev/null | wc -l); [ -n "$crk" ] || crk=0',
614	  "  cronn=$((cronn+crk))",
615	  "done",
616	  "printf 'CRONCOUNT\\t%s\\n' \"$cronn\"",
