634	  "      next*|next-server*) rt=next;;",
635	  "      dotnet) rt=dotnet;;",
636	  "    esac",
637	  '    [ -n "$rt" ] || continue',
638	  '    cwd=$(readlink "/proc/$ppid/cwd" 2>/dev/null)',
