648	  '  if [ -f "$d/package.json" ] || [ -f "$d/composer.json" ] || [ -f "$d/requirements.txt" ] || [ -f "$d/manage.py" ] || [ -f "$d/docker-compose.yml" ] || [ -f "$d/docker-compose.yaml" ] || [ -f "$d/compose.yml" ] || [ -f "$d/compose.yaml" ] || [ -d "$d/.git" ]; then',
