676	/**
677	 * Parse a MySQL/MariaDB client `--version` banner into a variant + major.minor.
678	 * MariaDB banners contain the literal "MariaDB" (e.g. "...Distrib 10.11.6-MariaDB");
679	 * Oracle MySQL banners look like "mysql  Ver 8.0.36 for Linux". Returns
680	 * {variant:null,version:null} when the banner is empty/unrecognised.
681	 */
682	export function parseMysqlVersion(raw: string): { variant: "mysql" | "mariadb" | null; version: string | null } {
683	  const s = cleanText(raw, 200);
684	  if (!s) return { variant: null, version: null };
685	  if (/mariadb/i.test(s)) {
686	    const m = /(\d+\.\d+)(?:\.\d+)?-MariaDB/i.exec(s) || /(\d+\.\d+)/.exec(s);
687	    return { variant: "mariadb", version: m ? m[1] : null };
688	  }
689	  const m = /Ver\s+(\d+\.\d+)/i.exec(s) || /(\d+\.\d+)/.exec(s);
690	  return { variant: "mysql", version: m ? m[1] : null };
691	}
692	
693	/** Parse a `psql --version` / `pg_config --version` banner into a major version.
694	 *  PostgreSQL ≥ 10 uses a single-number major ("15"); 9.x keeps major.minor. */
695	export function parsePgVersion(raw: string): string | null {
696	  const s = cleanText(raw, 200);
697	  const m = /(\d+(?:\.\d+)?)/.exec(s);
698	  if (!m) return null;
699	  const major = parseInt(m[1], 10);
700	  return Number.isFinite(major) && major >= 10 ? String(major) : m[1];
701	}
