// ===========================================================================
// `/home` EXPANSION — which machine are we asking?
// ===========================================================================
/**
 * The two questions the `/home` expansion has to ask, as an interface rather
 * than a `Client` — because the whole defect this seam exists to prevent was
 * asking the WRONG MACHINE.
 *
 * Incident (found by the 2026-07-27 line audit): `/home` is in `UNSAFE_EXACT`
 * (copying it wholesale would overwrite the new server's own accounts) AND in
 * `DEFAULT_PATHS` (`lib/actions-migrate.ts`), so it is in the default selection
 * of every migration. The fix for that — expand `/home` into its per-user
 * subdirectories — enumerated `/home` with `sh(conn, "ls -1 /home")`, and `conn`
 * is the TARGET connection. A freshly-provisioned Nxeon VPS has an empty (or
 * single-account) `/home`, so the list came back empty and the run pushed:
 *
 *     Copy /home — skipped — "the old server has no user home directories under /home"
 *
 * A statement about the OLD server, produced by looking at the NEW one. Every
 * home directory on the source was silently left behind, and on the HestiaCP /
 * cPanel layout the field notes describe (`/home/<user>/public_html`) that is
 * the customer's entire web estate. The previous version of this bug dropped
 * `/home` with a silent `.filter()`; this version dropped it with a sentence
 * that was not true.
 *
 * Naming the two sides in the type is the point: `listSourceHomes` cannot be
 * implemented against the target without the name reading as a lie.
 */
export type HomeExpansionHost = {
  /** `ls -1 /home` ON THE SOURCE — the machine we are migrating FROM. */
  listSourceHomes: () => Promise<string[]>;
  /**
   * Does the TARGET already own this account AND a home directory for it?
   * Overwriting one would break a login this platform created for the customer.
   */
  targetOwnsHome: (user: string) => Promise<boolean>;
};

export type HomeExpansion = {
  /** Absolute `/home/<user>` paths to add to the copy list. */
  copy: string[];
  /** Every directory we declined, with the honest reason. A selection we decline is a selection we must name. */
  skipped: MigrationStepResult[];
};

/**
 * Expand a `/home` selection into the per-user directories we are willing to
 * copy. Pure decision logic over the seam above: no SSH, no clock, no `Client`.
 *
 * Only names matching USER_RE survive, which is both the shell-inert guarantee
 * for `/home/<user>` and the reason `safeCopyTarget` cannot reject the result
 * (`/home` is in UNSAFE_EXACT; `/home/<label>` is not, and USER_RE admits
 * exactly one label with no `.`, `/` or metacharacter).
 */
export async function expandHomeSelection(host: HomeExpansionHost): Promise<HomeExpansion> {
  const skipped: MigrationStepResult[] = [];
  const copy: string[] = [];
  const names = [...new Set((await host.listSourceHomes()).map((s) => s.trim()).filter((s) => USER_RE.test(s)))].slice(0, 60);

  if (!names.length) {
    skipped.push({
      step: "Copy /home",
      status: "skipped",
      detail: "the old server has no user home directories under /home, so there was nothing to copy from it",
    });
    return { copy, skipped };
  }

  for (const u of names) {
    const dest = `/home/${u}`;
    if (!safeCopyTarget(dest)) continue; // unreachable for USER_RE names; kept as a hard floor
    if (await host.targetOwnsHome(u)) {
      skipped.push({
        step: `Copy ${dest}`,
        status: "skipped",
        detail: `the new server already has an account named ${u}, so its home directory was left alone — the old ${dest} is still on the old server, copy it by hand if you need it`,
      });
      continue;
    }
    copy.push(dest);
  }

  if (!copy.length) {
    skipped.push({
      step: "Copy /home",
      status: "skipped",
      detail: `every home directory on the old server (${names.slice(0, 6).join(", ")}${names.length > 6 ? " …" : ""}) collides with an account on the new server — none could be copied automatically`,
    });
  }
  return { copy, skipped };
}

/** Node-side wait. Used only to let systemd settle before we judge a unit. */
const delay = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

