/**
 * Build the read-only sweep. `dirs` are validated absolute paths and `needles`
 * are validated IPv4 addresses / hostnames (both shell-inert charsets), and the
 * script is written to the target over SFTP and run with `sh` rather than
 * assembled in a shell — so there is no injection surface.
 *
 * `SWEEP_OK` IS A MEASUREMENT, NOT A FAREWELL. It used to be the script's
 * unconditional last line, printed whatever had happened above it: the `find`
 * could produce an empty list, `timeout 120` could kill both grep passes, and
 * the marker still went out. `parseStaleSweep().ok` was introduced specifically
 * to separate "we looked and it is clean" from "we could not look", and the
 * caller pushes a clean bill of health — status `running` — on the strength of
 * it. A marker that cannot fail is the same defect as a score that cannot fail;
 * it just took a smaller shape.
 *
 * So `ok` is now earned: zero files enumerated means nothing was proven, and a
 * grep pass that `timeout` killed (or that died on a signal) clears it. The two
 * passes write through `$RC` rather than being judged by the pipeline's exit
 * status, because a pipeline's status is `awk`'s and says nothing about the grep
 * at its head.
 */
export function staleSweepScript(dirs: string[], needles: string[], work: string): string {
  const pruneExpr = SWEEP_EXCLUDE_DIRS.map((d) => `-name ${d}`).join(" -o ");
  const nameExcl = SWEEP_EXCLUDE_GLOBS.map((g) => `! -name '${g}'`).join(" ");
  const needleArgs = needles.map((n) => `-e ${n}`).join(" ");
  // One bounded grep pass: run it, record its REAL exit status in $RC, and clear
  // `ok` when that status means "killed" rather than "no matches". `timeout`
  // reports 124/137; `xargs` reports 125 when its child died on a signal; 126/127
  // are "could not run it at all". `xargs` reports 123 when grep merely exited 1
  // (no matches), which is the ordinary clean case and must NOT clear `ok`.
  const pass = (kind: string, grepArgs: string) => [
    "  echo 0 > \"$RC\"",
    `  ( $TO xargs -0 -r grep -I -H -n -o ${grepArgs} -- < "$LIST" 2>/dev/null; echo $? > "$RC" ) | head -n ${SWEEP_MAX_HITS} | while IFS= read -r hl; do`,
    `    printf '${kind}\\t%s\\n' "$hl"`,
    "  done",
    '  rc=$(cat "$RC" 2>/dev/null); [ -n "$rc" ] || rc=0',
    '  case "$rc" in 124|125|126|127|13[0-9]|14[0-9]) ok=0 ;; esac',
  ];
  return [
    "export LC_ALL=C",
    'if command -v timeout >/dev/null 2>&1; then TO="timeout 120"; else TO=""; fi',
    `LIST=${work}/stale-files.lst`,
    `RC=${work}/stale-rc`,
    // Nothing proven until something is actually read.
    "ok=0",
    // `grep -I` below skips binaries; the size cap and prune/exclude lists keep
    // this bounded even on a large tree.
    `find ${dirs.join(" ")} \\( -type d \\( ${pruneExpr} \\) -prune \\) -o ` +
      `\\( -type f -size -${SWEEP_MAX_FILE_SIZE} ${nameExcl} -print0 \\) 2>/dev/null > "$LIST"`,
    // An empty list means ZERO files were examined. Saying "nothing points at the
    // old server" on the back of that is answering the question without looking.
    'if [ -s "$LIST" ]; then',
    "  ok=1",
    // -o prints ONLY the matched needle, so a matched line containing a password
    // in a connection string never leaves the box. The needle pass is omitted
    // entirely when there is nothing to look for; the certificate pass still runs.
    ...(needles.length ? pass("HIT", `-F ${needleArgs}`) : []),
    ...pass("CERTREF", `-E '/etc/letsencrypt/live/[A-Za-z0-9._-]+'`),
    "fi",
    'rm -f "$LIST" "$RC"',
    // Printed ONLY when both passes ran over a non-empty file list.
    '[ "$ok" = 1 ] && printf \'SWEEP_OK\\t1\\n\'',
    "true",
    "",
  ].join("\n");
}

