// ---- Abandoned migrations: the credential promise, kept on the crash path ---
/**
 * How long a migration may sit unfinished with NO live job before it is declared
 * abandoned. Generous: a real lift-and-shift of a large box legitimately runs for
 * a long time, and while it does its job row is QUEUED or RUNNING, which exempts
 * it from this entirely.
 */
export const MIGRATION_ABANDON_MS = 3 * 60 * 60_000;

export type AbandonedMigrationInput = {
  status: string;
  finishedAt: Date | null;
  createdAt: Date;
  /** Is there a MIGRATE job for this migration still QUEUED or RUNNING? */
  hasLiveJob: boolean;
  now: number;
  maxAgeMs?: number;
};

/**
 * Is this migration abandoned — unfinished, with nothing left that could ever
 * finish it?
 *
 * WHY THIS EXISTS. Two documents promise the same thing in the same words:
 * `lib/actions-migrate.ts` ("They are CLEARED by the worker the moment the
 * migration finishes — success or failure — so a completed Migration row never
 * retains usable credentials") and this file's own header. Both are true for
 * every path that reaches `runMigration`'s try/catch. Neither is true for the
 * path where the worker never reaches it:
 *
 *   worker crash / restart  →  `reapStuckJobs` (worker/index.ts) re-QUEUEs the
 *   MIGRATE job  →  it crashes again  →  `attempts >= MAX_ATTEMPTS`  →  the job
 *   is marked FAILED and handed to `reconcileFailedJob`, which handles RESIZE and
 *   DISK_EXPAND and returns immediately for everything else.
 *
 * Nothing then touches the Migration row again. It keeps `status: "RUNNING"`
 * forever — the customer's wizard polls a progress bar that will never move — and
 * it keeps `sourcePasswordEnc`, which is the ROOT SSH PASSWORD OF ANOTHER
 * PROVIDER'S LIVE SERVER, encrypted at rest but retained indefinitely for a run
 * that ended hours ago. "Cleared when the run ends, success or failure" has to
 * include the failure mode where nothing was there to clear it.
 *
 * Pure so the rule is testable without a database, a worker or a clock.
 */
export function isAbandonedMigration(m: AbandonedMigrationInput): boolean {
  if (m.finishedAt) return false;
  if (m.status !== "PENDING" && m.status !== "RUNNING") return false;
  // Something can still finish it — leave it alone however long it takes.
  if (m.hasLiveJob) return false;
  return m.now - m.createdAt.getTime() >= (m.maxAgeMs ?? MIGRATION_ABANDON_MS);
}

/** What an abandoned migration is told, in the customer's words. */
const ABANDONED_MIGRATION_ERROR =
  "This migration stopped before it finished — the transfer was interrupted and nothing was left running that could pick it up. " +
  "Nothing on your old server was changed at any point, so it is still serving exactly as it was. Start the migration again when you're ready.";

/**
 * Settle every abandoned migration: mark it FAILED and CLEAR its stored source
 * credentials. See `isAbandonedMigration` for the crash path this closes.
 *
 * Returns how many it settled, so the caller can log a number it actually
 * counted rather than an assurance.
 */
export async function reapAbandonedMigrations(): Promise<number> {
  const rows = await db.migration.findMany({
    where: { finishedAt: null, status: { in: ["PENDING", "RUNNING"] } },
    select: { id: true, userId: true, status: true, createdAt: true, finishedAt: true, items: true, log: true },
    orderBy: { createdAt: "asc" },
    take: 100,
  });
  if (!rows.length) return 0;

  const now = Date.now();
  let reaped = 0;
  for (const m of rows) {
    const live = await db.job.findFirst({
      where: {
        type: "MIGRATE",
        status: { in: ["QUEUED", "RUNNING"] },
        payload: { path: ["migrationId"], equals: m.id },
      },
      select: { id: true },
    });
    if (!isAbandonedMigration({ status: m.status, finishedAt: m.finishedAt, createdAt: m.createdAt, hasLiveJob: !!live, now })) {
      continue;
    }
    const items = (m.items ?? {}) as MigrationItems;
    try {
      await db.migration.update({
        where: { id: m.id },
        data: {
          status: "FAILED",
          step: "Stopped before finishing",
          lastError: ABANDONED_MIGRATION_ERROR,
          finishedAt: new Date(),
          log: appendLog(m.log, `ERROR: ${ABANDONED_MIGRATION_ERROR}`),
        },
      });
      // The whole point of the sweep. Runs even if the status write above threw,
      // because retaining the credential is the worse of the two failures.
    } finally {
      await clearSecrets(m.id, items).catch((e) =>
        console.error(`[migrate] could not clear secrets for abandoned migration ${m.id}:`, e)
      );
    }
    reaped++;
    await notify(
      m.userId,
      "Migration stopped before it finished",
      ABANDONED_MIGRATION_ERROR,
      "/dashboard/migrate"
    );
  }
  if (reaped) console.log(`[migrate] settled ${reaped} abandoned migration(s) and cleared their stored source credentials`);
  return reaped;
}

/** How long after a migration finishes we keep watching for the DNS cutover. */
const TLS_WATCH_DAYS = 14;

export async function postCutoverTlsSweep(): Promise<void> {
  // Settled here rather than in its own registered sweep because this function is
  // the migration subsystem's ONLY periodic entry point (worker/index.ts calls it
  // every 30 minutes) and an unfinished migration holding a source root password
  // must not wait for a new registration to be plumbed in. It is wrapped so a
  // failure here can never stop the certificate pass that follows.
  await reapAbandonedMigrations().catch((e) => console.error("[migrate] abandoned-migration sweep failed:", e));

  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);

