101	  /** Positions where a `/` begins a regex literal rather than a division. */
102	  const REGEX_PRECEDERS = new Set(["", "(", ",", "=", ":", "[", "!", "&", "|", "?", "{", "}", ";", "+", "-", "*", "%", "~", "^", "<", ">", "\n"]);
103	  const REGEX_KEYWORDS = /\b(return|typeof|case|in|of|delete|void|instanceof|new|do|else|yield|await)\s*$/;
104	
105	  while (i < n) {
106	    const c = src[i];
107	    const next = src[i + 1];
108	
109	    if (quote) {
110	      out += c;
111	      if (c === "\\") {
112	        // Escape: copy the escaped character too, so `\"` never closes a string.
113	        if (i + 1 < n) out += src[i + 1];
114	        i += 2;
115	        continue;
116	      }
117	      if (c === quote) quote = null;
118	      i++;
119	      continue;
120	    }
121	
122	    if (c === '"' || c === "'" || c === "`") {
123	      quote = c;
124	      out += c;
125	      prev = c;
126	      i++;
127	      continue;
128	    }
129	
130	    // `//` and `/*` are ALWAYS comments in valid JS — a regex literal cannot
131	    // begin with an unescaped `/` or a `*`. So comments win unconditionally, and
132	    // the regex branch below only ever sees a genuine literal.
133	    if (c === "/" && next === "/") {
134	      while (i < n && src[i] !== "\n") i++;
135	      out += " ";
136	      continue;
137	    }
138	    if (c === "/" && next === "*") {
139	      i += 2;
140	      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i++;
141	      i += 2;
142	      out += " ";
143	      continue;
144	    }
145	
146	    // A regex literal must be consumed whole, or its escaped slashes (`\/\/` in
147	    // `/^https?:\/\//`) look like the start of a comment and eat the rest of the
148	    // line — silently deleting real code from everything asserted below.
149	    if (c === "/" && (REGEX_PRECEDERS.has(prev) || REGEX_KEYWORDS.test(out))) {
150	      out += c;
151	      i++;
152	      let inClass = false;
153	      for (; i < n; i++) {
154	        const r = src[i];
155	        out += r;
156	        if (r === "\\") {
157	          if (i + 1 < n) out += src[i + 1];
158	          i++;
159	          continue;
160	        }
161	        if (r === "[") inClass = true;
162	        else if (r === "]") inClass = false;
163	        else if (r === "/" && !inClass) {
164	          i++;
165	          break;
166	        } else if (r === "\n") {
167	          // Not a regex after all (unterminated) — stop rather than run away.
168	          i++;
169	          break;
170	        }
171	      }
172	      prev = "/";
173	      continue;
174	    }
175	
176	    out += c;
177	    if (!/\s/.test(c) || c === "\n") prev = c;
178	    i++;
179	  }
180	  return out;
181	}
